insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('storage', 'beans', 'تخزين البن', 'Storing coffee', 'احفظ البن في وعاء محكم بعيد عن الضوء والحرارة والرطوبة، واطحن حاجتك قبل التحضير. اشترِ كمية تناسب استهلاكك. للتخزين الطويل، استخدم عبوات صغيرة محكمة في الفريزر وخذ حاجتك دون تكرار إخراج الكمية كلها وإرجاعها؛ الرطوبة والروائح تؤثر في البن.', 'Keep beans airtight, away from light, heat and moisture. Grind what you need before brewing and buy an amount suited to your use. For longer storage, freeze in small airtight portions; take what you need without repeatedly moving the whole supply in and out. Moisture and odors affect coffee.', 'قسّم الكمية الكبيرة إلى عبوات صغيرة. اترك العبوة المجمدة مغلقة حتى تصل إلى حرارة الغرفة قبل فتحها لتقليل التكاثف.', 'Divide a large supply into small airtight portions. Let a frozen package reach room temperature while sealed before opening to reduce condensation.', 'NCA — Coffee storage', 'https://www.aboutcoffee.org/beans/storage-and-shelf-life/', '[]'::jsonb, 55, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('water', 'water', 'العسر والقلوية وTDS', 'Hardness, alkalinity and TDS', 'نوع الماء يغيّر طعم القهوة. العسر يقيس معادن مثل الكالسيوم والمغنيسيوم، والقلوية تخفف الإحساس بالحموضة؛ زيادتها قد تجعل الكوب مسطحًا. رقم TDS وحده لا يبين توازن هذه المعادن. قارن مصدرَي ماء مع تثبيت البن والوصفة. للإسبريسو، اتبع حدود الماء التي يحددها صانع الماكينة لتجنب الترسبات.', 'Water changes coffee flavor. Hardness reflects minerals such as calcium and magnesium; alkalinity buffers acidity, and too much can flatten the cup. TDS alone does not show the mineral balance. Compare two water sources while keeping coffee and recipe fixed. For espresso, follow your machine manufacturer’s water limits to manage scale.', 'العسر والقلوية قياسان مختلفان حتى لو كُتبا بوحدة ppm ككربونات الكالسيوم. جهاز TDS لا يفصل بينهما؛ تحتاج تحليلًا أو اختبارين مناسبين.', 'Hardness and alkalinity are separate measurements even when both are expressed in ppm as calcium carbonate. A TDS meter cannot separate them; use suitable tests or a water analysis.', 'Barista Hustle — Water hardness', 'https://www.baristahustle.com/water-hardness/', '[]'::jsonb, 5, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('processing', 'beans', 'معالجات البن', 'Coffee processing', 'المغسولة: تزال القشرة واللب والطبقة اللزجة قبل تجفيف البذور. المجففة: تجف الحبة داخل كرزة القهوة كاملة. العسلية: تزال القشرة وتبقى كمية من الطبقة اللزجة أثناء التجفيف؛ الاسم لا يعني إضافة عسل. المعالجة تؤثر في الطعم مع الصنف والمنشأ والتحميص والتحضير، لذلك لا تحدد وصفة واحدة لكل معالجة.', 'Washed processing removes the fruit and mucilage before drying the seeds. Natural processing dries the whole cherry. Honey processing removes the skin and keeps some mucilage during drying; its name does not mean honey is added. Processing affects taste alongside variety, origin, roasting and brewing, so one recipe cannot fit every coffee with the same process.', 'المعالجة اللاهوائية تصف بيئة تخمير محدودة الأكسجين، وقد تُدمج مع مغسول أو مجفف. اقرأ تفاصيل المنتج بدل افتراض أن الاسم يضمن نكهة ثابتة.', 'Anaerobic processing describes a low-oxygen fermentation environment and can accompany washed or natural processing. Read producer details rather than assuming the name guarantees one flavor.', 'NCA — Coffee processes', 'https://www.aboutcoffee.org/beans/processes/', '[]'::jsonb, 55, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('bloom', 'brewing', 'البلوم وخروج الغاز', 'Blooming and gas release', 'البلوم هو ترطيب البن بقليل من ماء التحضير قبل بقية الصبات. يساعد على وصول الماء لكل البن وخروج غازات التحميص، لذلك قد ينتفخ البن الطازج أكثر. حافظ على ترطيب متجانس وطريقة تحريك ثابتة. كمية الماء والانتظار تتبع الوصفة؛ كبر البلوم وحده لا يقيس جودة البن.', 'Blooming wets the grounds with a small part of the brew water before the remaining pours. It helps wet the bed evenly and releases roasting gas, so fresh coffee can expand more. Keep wetting and agitation consistent. Follow the recipe for water amount and waiting time; bloom size alone does not measure coffee quality.', 'تأكد أن كل طبقة البن ابتلت؛ اسكب بهدوء وسجّل طريقة التحريك. إذا غيّرت مدة البلوم، ثبّت بقية الصبات حتى تكون المقارنة مفيدة.', 'Wet the whole bed gently and record agitation. When changing bloom duration, keep the other pours fixed for a useful comparison.', 'Barista Hustle — Blooming', 'https://www.baristahustle.com/lesson/p-1-05-blooming/', '[]'::jsonb, 55, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('rest', 'beans', 'راحة البن بعد التحميص', 'Resting after roasting', 'بعد التحميص يخرج الغاز تدريجيًا، ومدة الراحة تختلف حسب البن ودرجة التحميص. اتبع توصية محمصتك وسجّل تغير الطعم مع الأيام. لا كابرا توصي لبنها براحة عشرة أيام على الأقل وقد يناسب بعض بنها الكثيف وقت أطول؛ هذا يخص تحميصها وليس قاعدة لكل المحامص.', 'Roasting gas leaves the beans gradually, and resting time varies with the coffee and roast. Follow your roaster’s guidance and track taste over time. La Cabra recommends at least ten days for its own coffee and sometimes longer for dense coffees; that is its roast guidance, not a rule for every roaster.', 'تذوق نفس البن في عدة أيام بنفس الوصفة وسجل التدفق والطعم. تاريخ التحميص وحده لا يحدد يوم الذروة لكل البن.', 'Taste the same coffee on several days with the same recipe, recording flow and taste. Roast date alone cannot predict a universal peak day.', 'La Cabra — Resting coffee', 'https://us.lacabra.com/pages/resting-coffee', '[]'::jsonb, 55, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast', 'roasting', 'درجات التحميص', 'Roast levels', 'التحميص الفاتح غالبًا يبرز شخصية البن، والغامق يبرز نكهات التحميص أكثر. لون البن وأسماء درجات التحميص تختلف بين المحامص ولا تعني وحدها الجودة أو كمية الكافيين. ابدأ بوصفة المحمصة ثم عدّل عاملًا واحدًا بحسب الطعم.', 'Lighter roasts tend to emphasize the coffee’s character; darker roasts bring more roast flavors. Colors and roast names vary between roasters and alone do not establish quality or caffeine content. Start with the roaster’s recipe, then change one variable at a time based on taste.', 'الفاتح ليس مرادفًا لنقص التطوير، والغامق ليس مرادفًا للجودة المنخفضة. قارن لونًا وطعمًا مستهدفين، ولا تحكم من اسم الحمصة فقط.', 'Light does not mean underdeveloped, and dark does not automatically mean low quality. Compare intended color and flavor rather than judging roast names alone.', 'NCA — Coffee roasts', 'https://www.aboutcoffee.org/beans/roasts/', '[]'::jsonb, 55, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('pumps', 'equipment', 'المضخة الروتاري والاهتزازية', 'Rotary and vibration pumps', 'الاهتزازية: مدمجة وتستخدم حركة كهرومغناطيسية لضخ الماء، وهي شائعة في المكاين المنزلية. الروتاري: محرك يدير مضخة أكبر، وغالبًا تكون أهدأ. بعض مكاين الروتاري تقبل التوصيل بالماء، لكن تأكد من موديلك. كلتاهما قادرة على إسبريسو جيد؛ جودة الكوب تعتمد أيضًا على الطحن والحرارة وتوزيع البن. الروتاري ليست شرطًا لشراء ماكينة جيدة.', 'A vibration pump is compact and moves water using electromagnetic motion; it is common in home machines. A rotary pump uses a motor to drive a larger pump and is usually quieter. Some rotary machines support a mains water connection; check the model. Both can make good espresso. Grind, temperature and puck preparation also matter, so a rotary pump is not essential.', 'قارن الضجيج والمساحة وطريقة تزويد الماء وتكلفة الصيانة. إعداد ضغط المضخة يختلف عن التحكم بالتدفق أثناء الشوت؛ نوع المضخة وحده لا يثبت وجود أي منهما.', 'Compare noise, space, water supply and service cost. Setting pump pressure is different from controlling flow during a shot; pump type alone does not establish either feature.', 'Profitec — Pump systems', 'https://www.profitec-espresso.com/en/about-us', '[{"title":"Profitec — Pressure and service","url":"https://www.profitec-espresso.com/en/service"}]'::jsonb, 120, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('flow-control', 'equipment', 'التحكم بالتدفق وتعديل الضغط', 'Flow control and pressure adjustment', 'التحكم بالتدفق يغيّر كمية الماء الداخلة إلى مجموعة التحضير أثناء الشوت؛ يتغير الضغط معها بحسب مقاومة البن. ضبط ضغط المضخة يحدد إعدادًا مختلفًا ولا يعطيك بالضرورة تحكمًا لحظيًا. وجود عداد ضغط لا يعني أن الضغط قابل للبرمجة. قبل شراء قطعة Flow Control، تأكد من توافقها مع موديل الماكينة وإصدار مجموعة التحضير والضمان.', 'Flow control changes water entering the brew group during a shot; pressure responds to puck resistance. Adjusting pump pressure is a different setting and does not necessarily give control during extraction. A pressure gauge does not imply programmable pressure. Before buying a flow-control kit, check compatibility with the exact machine, group version and warranty.', 'ابدأ بوصفة ثابتة وسجل الجرعة والناتج والوقت، ثم قارن تغيير التدفق وحده. لا أفترض أن كل مجموعة E61 تقبل القطعة نفسها؛ أعطني الموديل الكامل أو دليل الشركة للتحقق.', 'Start with a repeatable recipe and record dose, yield and time, then compare a flow change alone. E61 groups do not automatically accept the same kit; supply the full model or manufacturer manual to check.', 'Profitec — DRIVE flow control', 'https://www.profitec-espresso.com/en/products/drive', '[{"title":"Profitec — Pressure and service","url":"https://www.profitec-espresso.com/en/service"}]'::jsonb, 125, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('machine-choice', 'equipment', 'اختيار ماكينة الإسبريسو', 'Choosing an espresso machine', '• للإسبريسو أكثر من الحليب: قارن الثبات الحراري وضبط الطحن؛ الغلاية الواحدة قد تكفي إذا تقبل الانتظار بين التحضير والتبخير.
• للحليب المتكرر: قارن سرعة الانتقال للبخار، أو الغلايتين والمبادل الحراري للتحضير والتبخير معًا.
• إذا ما عندك طاحونة: احسب ماكينة وطاحونة مناسبة للإسبريسو ضمن المجموع، أو قارن جهازًا بطاحونة مدمجة.
• قبل الشراء: تحقق من الضمان والصيانة والجهد الكهربائي والمقاس؛ رقم البار وحده لا يكفي للاختيار.', '• Mostly espresso: compare temperature stability and grind adjustment; a single boiler may suit you if waiting between brewing and steaming is acceptable.
• Frequent milk drinks: compare steam transition speed, or dual-boiler and heat-exchanger designs for simultaneous work.
• No grinder yet: budget for a machine plus an espresso-capable grinder, or compare an integrated-grinder model.
• Before buying: check warranty, service, voltage and space; advertised bar pressure alone is not enough.', 'أعطني عدد الأكواب المتتالية، ونوع المشروبات، وهل عندك طاحونة، والميزانية مع العملة. أقدر أقارن المواصفات المنشورة؛ السعر والتوفر يحتاجان عرضًا مؤرخًا من بائع.', 'Tell me consecutive drink count, drink types, whether you own a grinder and your budget with currency. I can compare published specifications; price and stock require a dated seller offer.', 'Profitec — Single-boiler GO', 'https://www.profitec-espresso.com/en/products/go', '[{"title":"LELIT — Elizabeth dual boiler","url":"https://www.lelit.com/en-us/product/elizabeth-pesel01"},{"title":"Profitec — PRO 400 heat exchanger","url":"https://www.profitec-espresso.com/en/products/pro-400"}]'::jsonb, 115, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('integrated-grinder', 'equipment', 'الطاحونة المدمجة أم المنفصلة؟', 'Integrated or separate grinder?', 'المدمجة تجمع الطحن والتحضير في جهاز واحد وتقلل عدد الأجهزة على الطاولة. المنفصلة تسمح باختيار طاحونة تناسب استخدامك وترقيتها أو صيانتها بشكل مستقل؛ هذه فائدة عملية وليست ضمانًا لطعم أفضل. للإسبريسو، المهم قدرة الطاحونة على ضبط الطحن بدقة وتكرار الجرعة. إذا عندك طاحونة جيدة، قارن تكلفة الماكينة وحدها قبل دفع قيمة طاحونة مدمجة إضافية.', 'An integrated grinder combines grinding and brewing in one appliance, reducing separate devices on the counter. A separate grinder lets you choose, upgrade and service it independently; that flexibility does not guarantee better taste. Espresso needs sufficiently fine adjustment and repeatable dosing. If you already own a suitable grinder, compare machine-only cost before paying for another integrated grinder.', 'اذكر موديل طاحونتك الحالية، وهل تستخدمها للإسبريسو فقط أو للترشيح أيضًا. لا أنقل أرقام الطحن بين الطواحين؛ حتى الموديل نفسه يتأثر بنقطة الصفر والمعايرة.', 'Give your current grinder model and whether you use it for espresso only or filter coffee too. Grind numbers do not transfer between grinders; even the same model depends on zero point and calibration.', 'Sage — Barista Pro integrated grinder', 'https://www.sageappliances.com/en-gb/product/bes878', '[{"title":"Baratza — Choosing an espresso grinder","url":"https://www.baratza.com/en-us/product/encoretm-esp-zcg495"}]'::jsonb, 120, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('moka-safety', 'brewing', 'الموكا بوت وصمام الأمان', 'Moka pot and safety valve', 'في موكا إكسبرس، املأ القاعدة إلى ما دون صمام الأمان، وضع البن دون كبسه. توصي بياليتي بحرارة منخفضة إلى متوسطة؛ أبقِ لهب الغاز بعيدًا عن جوانب الإبريق، وارفعه عن الحرارة عند امتلائه. لا تفترض جرعة أو كمية ماء ثابتة لكل أحجام الموكا.', 'For Moka Express, fill the base below the safety valve and add grounds without tamping. Bialetti recommends low-to-medium heat; keep a gas flame from reaching up the sides and remove the pot from heat when full. Different pot sizes do not share one fixed dose or water amount.', 'راجع دليل موديلك قبل الاستخدام والتنظيف، ولا تنقل تعليمات التوافق مع الموقد إلى كل موديلات الموكا. دليل بياليتي يربط مدة التحضير بحجم الإبريق وشدة الحرارة، وليست رقمًا عامًا للطاحونة أو وصفة موحدة.', 'Use your model’s instructions for operation, cleaning and hob compatibility. Bialetti relates brewing duration to pot size and heat intensity; it is not a universal grinder setting or recipe.', 'Bialetti — How to use the Moka Express', 'https://bialetti-cookware.zendesk.com/hc/en-us/articles/5416235346322-How-to-use-the-Moka-Express', '[]'::jsonb, 115, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('espresso-dial-in', 'brewing', 'ضبط وصفة الإسبريسو', 'Dialing in espresso', 'اضبط الإسبريسو بقياس الجرعة والناتج والوقت. ثبّت الجرعة والناتج ثم قارن تغيير الطحن: الأنعم يبطئ التدفق والأخشن يسرّعه غالبًا. وصفة فلير 58 بلس نقطة بداية لجهاز وسلة محددين؛ لا تنقل وقتها أو ضغطها إلى كل ماكينة.', 'Dial in espresso by weighing dose and yield and recording time. Hold dose and yield fixed while adjusting grind: finer usually slows flow and coarser speeds it up. Flair 58 Plus guidance is a starting point for its machine and basket; do not transfer its time or pressure to every machine.', 'غيّر عاملًا واحدًا وسجّل الطعم. اذكر هل الوقت يشمل الترطيب المسبق، ولا تطلب رقم طاحونة دون معرفة موديلها.', 'Change one variable and record taste. State whether timing includes preinfusion; a grinder number requires its model.', 'Flair — Dialing in espresso', 'https://flairespresso.com/blogs/news/dialing-in-flair-58-plus-manual-espresso-maker', '[]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('immersion-percolation', 'brewing', 'النقع والترشيح والفرنش برس', 'Immersion, percolation and French press', 'في الفرنش برس ينقع البن في الماء ثم يفصله مكبس بفلتر معدني. في الترشيح يمر الماء عبر طبقة البن. السويتش يجمع المرحلتين بصمامه؛ اتبع أوقات فتحه وإغلاقه في الوصفة. جرعة الإسبريسو وناتجه لا يمثلان ماء النقع؛ سجّل قياسات جديدة عند تغيير الطريقة.', 'French press steeps coffee in water before a metal-filter plunger separates it. Percolation moves water through a bed of grounds. A Switch combines stages using its valve; follow the recipe’s open and close times. Espresso yield does not represent steeping water. Record fresh measurements when changing methods.', 'للفرنش برس، اكبس بهدوء وانقل المشروب بعد التحضير. نظّف الإبريق والفلتر بعد الاستخدام؛ بقايا البن والزيوت تؤثر في الكوب التالي.', 'Plunge gently and decant after brewing. Clean the French press and filter after use; leftover grounds and oils affect the next cup.', 'NCA — French press', 'https://www.aboutcoffee.org/brewing/french-press-coffee/', '[{"title":"HARIO — Switch with Partners Coffee","url":"https://www.hario-usa.com/blogs/recipes-and-more-from-friends/v60-switch-recipe-with-partners-coffee"}]'::jsonb, 100, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('flash-brew', 'brewing', 'القهوة المثلجة وماء التحضير والثلج', 'Flash brew, brew water and ice', 'الفلاش برو يستخلص القهوة بماء ساخن فوق ثلج موزون. سجّل ماء الصب والثلج كلًا على حدة؛ الثلج ليس ماء يمر عبر البن، وليس كل وزن الماء والثلج هو وزن المشروب النهائي. مثال منشور لـ OREA V3: 18 g بن، 160 ml ماء عند 94°C و140 g ثلج. وصفة جهاز محدد وليست تحويلًا تلقائيًا لأي وصفة ساخنة.', 'Flash brewing extracts coffee with hot water onto weighed ice. Record poured water and ice separately: ice does not pass through the grounds, and combined input water and ice are not the measured beverage yield. OREA’s V3 example uses 18 g coffee, 160 ml water at 94°C and 140 g ice. It is a device-specific published recipe, not an automatic conversion of any hot recipe.', 'راجع مصدر الوصفة ونوع الفلتر والطاحونة. لا تضاعف ماء الصب بإضافة وزن الثلج إليه؛ افصل مرحلة الاستخلاص عن التبريد والتخفيف، ثم قارن الطعم بعد التحريك.', 'Check the recipe source, filter and grinder. Do not count ice as additional poured extraction water. Separate extraction from cooling and dilution, then compare taste after stirring.', 'OREA — V3 THE ICE', 'https://www.orea.uk/guides-v3', '[]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('cold-brew', 'brewing', 'الكولد برو والاستخلاص البارد', 'Cold brew and cold extraction', 'الكولد برو يستخلص البن بالماء البارد، بخلاف الفلاش برو الذي يستخدم ماء ساخنًا ثم يبرده الثلج. مثال HARIO Mizudashi ينقع البن في سلة ترشيح داخل الماء في الثلاجة. الجرعة والماء والمدة تتبع دليل مقاس الأداة والوصفة؛ سعة الإبريق المكتوبة ليست بالضرورة كمية ماء التحضير أو وزن الناتج.', 'Cold brew extracts grounds with cold water, whereas flash brew uses hot water and then ice to chill it. HARIO’s Mizudashi steeps grounds in a filter basket in water in the refrigerator. Dose, water and time belong to the specific model size and recipe; stated pitcher capacity is not necessarily brew-water input or beverage weight.', 'دوّن جرعة البن وماء النقع والمدة وناتج التصفية وأي ماء تخفيف بشكل منفصل. لا تفترض أن كل كولد برو مركز يحتاج تخفيفًا، ولا تنقل مقادير مقاس إبريق إلى مقاس آخر بلا دليل.', 'Record dose, steeping water, time, filtered yield and any dilution water separately. Not every cold brew is a concentrate that needs dilution. Do not transfer one pitcher size’s quantities to another without its guide.', 'HARIO — Mizudashi', 'https://www.hario-usa.com/products/mizudashi-cold-brew-coffee-pot', '[]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('bypass-dilution', 'brewing', 'التخفيف والبايباس بعد الاستخلاص', 'Dilution and bypass after extraction', 'البايباس يضيف ماء لا يمر عبر البن إلى المشروب المستخلص. التخفيف يقلل تركيزه، لكنه لا يستخلص مواد إضافية من البن بعد فصل المشروب عنه. سجّل ماء التحضير وماء التخفيف والناتج المقاس منفصلة. إرشادات SCAA للبايباس تربط الوصفة بحجم الدفعة والطعم؛ لا توجد نسبة تخفيف واحدة لكل البن والأدوات.', 'Bypass adds water that does not pass through the grounds to the extracted beverage. Dilution lowers concentration but does not extract more from grounds once the beverage is separated. Record brew water, dilution water and measured beverage yield separately. SCAA’s bypass guidance relates the recipe to batch volume and taste; no single dilution percentage suits every coffee and brewer.', 'أضف ماء التخفيف بوزن مسجل وعلى مراحل وتذوق. المشروب المخفف والمشروب الذي مر فيه كل الماء عبر البن قد يختلفان حتى لو تساوى وزن التقديم. التخفيف وحده لا يعالج استخلاصًا غير متجانس.', 'Add weighed dilution water in stages and taste. A diluted beverage and one made with all water through the bed can differ even at equal serving weight. Dilution alone cannot correct uneven extraction.', 'SCAA — By-Pass Best Practices (2016)', 'https://scagermany.coffee/wp-content/uploads/2021/02/best-practices-bypass-brewing.pdf', '[]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('batch-scaling', 'brewing', 'تكبير وصفة الترشيح لكوبين', 'Scaling a filter recipe for two cups', 'ضرب الجرعة والماء في العدد نفسه يحافظ على النسبة حسابيًا، لكنه يغير عمق طبقة البن والتدفق. استخدم وصفة منشورة لحجم الأداة. OREA V4 EASY FOR TWO يحدد 25 g بن و400 ml ماء، وطحنة أخشن من وصفته الفردية مع قاعدة FAST وفلتره المحدد. لا تضاعف أوقات الصب أو تنقل ضبط الطحن إلى جهاز آخر تلقائيًا.', 'Multiplying dose and water by the same number preserves the arithmetic ratio but changes bed depth and flow. Use a published recipe for the brewer capacity. OREA’s V4 EASY FOR TWO uses 25 g coffee and 400 ml water, with a coarser grind than its single-cup version, FAST bottom and specified filter. Do not automatically double pour times or transfer grinder settings to another model.', 'تحقق من سعة الأداة والفلتر، وسجل كل صبة والوقت النهائي كنطاق المصدر. غيّر عاملًا واحدًا وقارن الطعم؛ نسبة ثابتة لا تضمن استخلاصًا مطابقًا عند زيادة حجم الدفعة.', 'Check brewer and filter capacity. Record each pour and the publisher’s final-time range. Change one variable and compare taste; a fixed ratio does not guarantee identical extraction after scaling.', 'OREA — V4 EASY FOR TWO', 'https://www.orea.uk/guides-v4', '[]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('coffee-basics', 'beans', 'من الشجرة إلى الكوب', 'From seed to cup', 'حبة القهوة بذرة داخل كرزة. يحدد الصنف والبيئة والنضج والمعالجة نقطة البداية، ثم يصنع التحميص الروائح ويستخلصها الماء. اسم البلد وحده لا يضمن إيحاءًا محددًا؛ اقرأ بيانات المحصول ثم تذوقه.', 'A coffee bean is a seed inside a cherry. Variety, environment, ripeness and processing shape the raw material; roasting creates aromas and brewing extracts them. A country name alone does not guarantee a flavor note. Read the lot information, then taste it.', 'قارن محصولين بوصفة واحدة، وسجل الصنف والمعالجة والتحميص وتاريخ التحضير. هذا يفصل أثر البن عن اختلاف وصفتك.', 'Compare two lots using one recipe. Record variety, processing, roast and brew date to separate coffee differences from recipe changes.', 'NCA — What is coffee?', 'https://www.aboutcoffee.org/origins/what-is-coffee/', '[]'::jsonb, 20, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('varieties', 'beans', 'أرابيكا وروبوستا والأصناف', 'Species and varieties', 'أرابيكا وروبوستا نوعان نباتيان؛ جيشا وبوربون وتيبيكا أصناف داخل أرابيكا. الصنف يؤثر في القابلية الزراعية والطعم، لكن المنشأ والمعالجة والتحميص عوامل مشتركة. اسم الصنف وحده ليس تقييمًا للجودة.', 'Arabica and robusta are species; Gesha, Bourbon and Typica are arabica varieties. Variety affects agronomic traits and flavor potential, alongside origin, processing and roast. A variety name alone is not a quality score.', 'اقرأ بطاقة المحصول كاملة بدل اختيار البن من اسم الصنف فقط، وقارن وصف المحمصة بما تتذوقه.', 'Read the complete lot card rather than buying only by variety. Compare the roaster’s description with your own tasting.', 'World Coffee Research — Varieties', 'https://varieties.worldcoffeeresearch.org/', '[]'::jsonb, 60, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('green-coffee', 'beans', 'اختيار البن الأخضر', 'Choosing green coffee', 'قبل التحميص، سجل المنشأ والصنف والمعالجة والمحصول والرطوبة والكثافة إن كانت مقاسة. افحص التجانس والعيوب ورائحة العينة. الأخضر قد يكون مائلًا للرمادي أو الأصفر، والديكاف قد يبدأ بنيًا؛ اللون وحده لا يثبت النضارة أو الجودة.', 'Before roasting, record origin, variety, process, lot, moisture and density when measured. Inspect uniformity, defects and sample aroma. Green coffee can look grayish or yellowish; decaf can start brown. Color alone does not establish freshness or quality.', 'استخدم نفس المحصول ووزن الدفعة في تجربة التحميص. لا تنقل إعداد حمصة ناجحة إلى بن مختلف دون تجربة جديدة.', 'Keep the same lot and batch weight during roast experiments. Do not transfer a successful profile to a different coffee without another trial.', 'SCA — Physical coffee assessment', 'https://sca.coffee/value-assessment', '[]'::jsonb, 65, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('decaf', 'beans', 'القهوة منزوعة الكافيين', 'Decaffeinated coffee', 'إزالة الكافيين تتم عادة قبل التحميص بعمليات مختلفة، والديكاف ليس خاليًا تمامًا من الكافيين. المعالجة تغيّر شكل البن وسلوكه؛ لا تحكم على درجة حمصته من لون الحبة وحده ولا تنسخ طحن البن العادي مباشرة.', 'Decaffeination generally happens before roasting, using different processes. Decaf still contains some caffeine. Processing changes bean appearance and behavior; do not judge its roast solely by color or copy another coffee’s grind setting.', 'ابدأ بتوصية المحمصة، ثم سجل الطعم وتدفق التحضير. عدّل خطوة واحدة مع تثبيت الجرعة والناتج.', 'Start with the roaster’s advice and record taste and brew flow. Change one variable with dose and yield held fixed.', 'NCA — Decaf', 'https://www.aboutcoffee.org/beans/decaf-coffee/', '[]'::jsonb, 70, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('grind-size', 'grinding', 'درجة الطحن حسب التحضير', 'Grind size by method', 'الإسبريسو يحتاج عادة طحنًا أنعم من الترشيح، لكن الوصفة والأداة والبن تحدد الضبط. النعومة تزيد المساحة المعرضة للماء وقد تبطئ التدفق. ابدأ من دليل طاحونتك، وثبّت الجرعة والنسبة ثم غيّر الطحن قليلًا وتذوق. رقم الطاحونة ليس وحدة مشتركة بين الموديلات.', 'Espresso usually needs a finer grind than filter brewing, but brewer, recipe and coffee determine the setting. Finer particles increase exposed surface and can slow flow. Start with your grinder guide, keep dose and ratio fixed and make small changes by taste. Grinder numbers are not transferable units.', 'إذا صار التدفق غير منتظم، راجع التوزيع والفلاتر قبل زيادة النعومة. أعطني موديل الطاحونة وطريقة التحضير حتى نرجع لإرشادات الموديل.', 'If flow becomes uneven, check distribution and filters before grinding finer. Give the grinder model and brewing method to consult its guidance.', 'Barista Hustle — Grind size', 'https://www.baristahustle.com/lesson/ae-1-03-grind-size/', '[]'::jsonb, 15, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('burrs', 'grinding', 'التروس المسطحة والمخروطية', 'Flat and conical burrs', 'التروس المسطحة والمخروطية هندستان للطحن، ولا تضمن إحداهما كوبًا أفضل دائمًا. شكل الأسنان والمحاذاة والسرعة والبن يؤثر في توزيع الجسيمات. اختر طاحونة تناسب الإسبريسو أو الترشيح، وتحقق من مدى الضبط والصيانة والاحتباس.', 'Flat and conical burrs are different grinding geometries; neither guarantees a better cup. Tooth design, alignment, speed and coffee influence particle distribution. Choose for espresso or filter use, then check adjustment range, serviceability and retention.', 'للمقارنة، اضبط كل طاحونة لأفضل طعم بدل استخدام نفس رقم الطحن. سجل الوصفة والجرعة والناتج والتكرار.', 'Dial each grinder for its best taste rather than comparing the same dial number. Record recipe, dose, output and repeatability.', 'Barista Hustle — Grinding methods', 'https://www.baristahustle.com/lesson/ae-1-02-grinding-methods/', '[]'::jsonb, 70, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('grinder-calibration', 'grinding', 'الصفر والكليكات والمعايرة', 'Zero, clicks and calibration', 'الصفر والكليكات يتبعان موديل الطاحونة وإصدار التروس. في C40 القياسية، توصيات Comandante كبداية: 7–13 كليك للإسبريسو و18–35 للترشيح، وليست وصفة لكل بن. Red Clix يغيّر عدد الخطوات. لا تجبر التروس على الانغلاق ولا تعاير جهازًا بطريقة تخص موديلًا آخر.', 'Zero and clicks depend on grinder model and burr version. For a standard C40, Comandante suggests starting at 7–13 clicks for espresso and 18–35 for filter, then dialing in. Red Clix changes the step count. Never force burrs shut or apply another model’s calibration procedure.', 'سجل الموديل وإصدار المحور ونقطة الصفر مع الوصفة؛ هذا يجعل رقم الطحن قابلًا للتكرار داخل نفس الجهاز.', 'Record the model, axle version and zero reference with the recipe so the setting is reproducible on that grinder.', 'Comandante — C40 FAQ', 'https://comandantegrinder.com/pages/faq', '[]'::jsonb, 90, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('retention', 'grinding', 'احتباس البن والتنظيف', 'Retention and grinder care', 'الاحتباس هو البن الذي يبقى داخل الطاحونة؛ يختلف عن تبادل البن القديم بالجديد. زن الداخل والخارج وسجل الفرق، لكن تطابق الوزن لا يثبت عدم وجود تبادل. نظف حسب دليل الموديل؛ لا تغسل التروس أو تنقعها إلا إذا سمح المصنع.', 'Retention is coffee left inside the grinder, distinct from old grounds exchanging with new grounds. Weigh input and output, but equal weights do not prove zero exchange. Follow model-specific cleaning guidance; wash or soak burrs only when the manufacturer permits it.', 'إذا تغير الطعم أو تكتل الطحن، ابدأ بتنظيف المخرج والتروس المسموح الوصول لها، ثم أعد الضبط. افصل الكهرباء قبل الصيانة.', 'If taste changes or grounds clump, clean the accessible outlet and burrs as instructed, then dial in again. Disconnect power before servicing.', 'Fellow — Ode Gen 2 guide', 'https://fellowproducts.com/pages/gear-guide-ode?view=gg-ode-2', '[]'::jsonb, 75, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('fines', 'grinding', 'الفاينز وتوزيع الجسيمات', 'Fines and particle distribution', 'الطحن ينتج أحجامًا متعددة؛ الفاينز جسيمات صغيرة قد تزيد الاستخلاص وتؤثر في مقاومة مرور الماء. كثرتها قد تعرقل التدفق، لكن إزالتها كلها ليست حلًا عامًا. النخل يغيّر الجرعة وتوزيع الأحجام، لذلك زن البن بعد النخل إن استخدمته.', 'Grinding produces many particle sizes. Fines can increase extraction and influence flow resistance; too many can impede flow, but removing all fines is not a universal improvement. Sifting changes both dose and distribution, so weigh the remaining coffee when using it.', 'قارن بنفس الجرعة بعد النخل والنسبة والماء، ثم سجل التدفق والطعم. لا تستخدم وقت التحضير وحده كدليل على الجودة.', 'Compare at the same post-sifting dose, ratio and water. Record flow and taste; brew time alone is not a quality measurement.', 'Barista Hustle — Regrinding experiment', 'https://www.baristahustle.com/regrinding/', '[]'::jsonb, 85, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('grinder-rpm', 'grinding', 'سرعة دوران الطاحونة', 'Grinder RPM', 'سرعة الدوران قد تغيّر التغذية والحرارة وتوزيع الجسيمات، لكن النتيجة تعتمد على تصميم الطاحونة والبن. لا توجد سرعة واحدة مثالية لكل طاحونة. استخدم نطاق الشركة، وغيّر السرعة وحدها ثم أعد ضبط الطحن عند الحاجة.', 'RPM can affect feeding, heat and particle distribution, depending on grinder design and coffee. There is no universal best speed. Stay within the manufacturer’s range, change only speed for the comparison and redial grind when needed.', 'قارن تكرار وزن الناتج والطعم في عدة تحضيرات. توقف عند أصوات احتكاك أو أعطال بدل محاولة علاجها بتغيير السرعة.', 'Compare output weight and taste over repeated brews. Stop for rubbing sounds or faults rather than masking them with a speed change.', 'Barista Hustle — Grinder RPM', 'https://www.baristahustle.com/coffee-grinder-rpm/', '[]'::jsonb, 90, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('water-treatment', 'water', 'الفلترة وRO وإعادة التمعدن', 'Filtration, RO and remineralization', 'فلتر الكربون يساعد في إزالة الكلور لكنه لا يعني خفض العسر. التناضح العكسي RO يقلل أملاحًا كثيرة وقد يحتاج مزجًا أو إعادة تمعدن. ماء التحضير المناسب للطعم قد لا يناسب الماكينة؛ اختبر العسر والقلوية والكلوريد وفق دليلها، ولا تعتمد على TDS وحده.', 'Carbon filtration can remove chlorine without necessarily reducing hardness. Reverse osmosis reduces many salts and may require blending or remineralization. Good-tasting brew water is not automatically suitable for a machine. Check hardness, alkalinity and chloride against its manual, not TDS alone.', 'اختبر الماء الداخل للماكينة بعد الفلتر وبدرجة حرارة الاختبار المطلوبة، وأعد القياس بعد تغيير الخرطوشة أو مصدر الماء.', 'Test water after treatment, before it enters the machine, at the required testing temperature. Retest after changing the cartridge or water source.', 'La Marzocco — Water calculator', 'https://techcenter.lamarzocco.com/en/watercalculator', '[]'::jsonb, 80, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('machine-water', 'water', 'الماء والتكلس في الماكينة', 'Machine water and scale', 'التكلس والتآكل يحتاجان فحص تركيب الماء، وليس رقم TDS فقط. مثال خاص بـ La Marzocco من وثيقة الماء: TDS ‏90–150 ppm، العسر الكلي 70–100 ppm، القلوية 40–80 ppm، والكلوريد 0–30 ppm. هذه حدود الشركة في الوثيقة، وليست معيارًا عامًا لكل المكاين؛ راجع دليل موديلك.', 'Scale and corrosion depend on water composition, not just TDS. A La Marzocco water specification gives TDS 90–150 ppm, total hardness 70–100 ppm, alkalinity 40–80 ppm and chloride 0–30 ppm. These are that manufacturer’s documented limits, not universal machine targets. Check your model’s manual.', 'لا تخلط قراءة العسر مع القلوية حتى لو كانت الوحدات ppm. أخبرني بموديل الماكينة ونتائج التحليل ووحداتها قبل تقييم الماء.', 'Do not confuse hardness with alkalinity even when both use ppm. Supply the machine model and test values with units before assessing water.', 'La Marzocco — Water specification', 'https://lamarzoccousa.com/wp-content/uploads/2023/09/Water-Specifications.pdf', '[]'::jsonb, 85, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('boilers', 'equipment', 'الغلاية الواحدة والمزدوجة', 'Single and dual boilers', 'الغلاية الواحدة تحتاج عادة الانتقال بين حرارة التحضير والبخار. الغلايتان تفصلان ماء التحضير عن البخار وتساعدان في العمل المتزامن. عدد الغلايات لا يحدد جودة الكوب وحده؛ راجع الثبات الحراري وسرعة الاستعداد والصيانة والمساحة.', 'A single boiler generally switches between brewing and steaming temperatures. Dual boilers separate brew water and steam and support simultaneous work. Boiler count alone does not determine cup quality; consider temperature stability, readiness, service and space.', 'حدد كم كوبًا متتاليًا تحضر وكم مشروب حليب. هذا يوضح احتياجك للبخار أكثر من مقارنة أسماء التقنيات وحدها.', 'State how many drinks you make consecutively and how many use milk. This clarifies steam needs better than comparing technology names alone.', 'La Marzocco — Dual boilers', 'https://nz.lamarzocco.com/news/blog/the-importance-of-dual-boilers/', '[]'::jsonb, 65, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('heat-exchanger', 'equipment', 'المبادل الحراري', 'Heat exchanger machines', 'المبادل الحراري يمرر ماء التحضير عبر مسار داخل غلاية ساخنة، ويمكن أن يوفر التحضير والبخار معًا. التحكم والسلوك الحراري يختلفان بين الموديلات؛ لا تفترض أن رقم حرارة الغلاية هو حرارة الماء عند البن، ولا تستخدم تفريغًا حراريًا موحدًا لكل جهاز.', 'A heat exchanger heats brew water through a path inside a hot boiler and can support brewing and steaming together. Temperature behavior varies by model. Boiler temperature is not necessarily puck temperature, and one cooling-flush routine does not fit every machine.', 'راجع تعليمات الاستعداد والتفريغ الخاصة بجهازك، وثبّت روتين التسخين قبل مقارنة الوصفات.', 'Follow your machine’s readiness and flushing instructions. Keep warm-up workflow fixed when comparing recipes.', 'Profitec — PRO 400 heat exchanger', 'https://www.profitec-espresso.com/en/products/pro-400', '[]'::jsonb, 90, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('pid', 'equipment', 'PID والثبات الحراري', 'PID and temperature stability', 'PID نظام تحكم يضبط التسخين اعتمادًا على قياس الحرارة؛ وجوده لا يعني أن قراءة الشاشة هي حرارة البن الفعلية. الثيرموبلوك يسخّن الماء أثناء مروره، والغلاية تخزن ماء ساخنًا. تصميم مجموعة التحضير وحساسات الجهاز مهم أيضًا.', 'PID controls heating using temperature feedback; the displayed reading is not necessarily the actual puck temperature. A thermoblock heats passing water, whereas a boiler stores hot water. Group design and sensor placement also matter.', 'بعد تغيير الإعداد انتظر الاستقرار حسب الدليل. لا تعدّل إزاحة الحساس أو إعدادات الصيانة الداخلية دون إرشادات الشركة.', 'After changing temperature, allow the machine to stabilize as instructed. Do not alter sensor offsets or internal service settings without manufacturer guidance.', 'Barista Hustle — PID', 'https://www.baristahustle.com/lesson/ae-5-03-the-pid/', '[]'::jsonb, 95, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('pressure', 'equipment', 'ضغط الإسبريسو والتدفق', 'Espresso pressure and flow', 'الضغط والتدفق مرتبطان بمقاومة قرص البن. ضغط المضخة المعلن ليس بالضرورة الضغط عند القرص. ليس رفع الضغط حلًا تلقائيًا للحموضة أو السرعة؛ ابدأ بالتوزيع والجرعة والطحن، ثم استخدم وصفة ودليل جهازك.', 'Pressure and flow interact with puck resistance. Advertised pump pressure is not necessarily pressure at the puck. Increasing pressure is not an automatic fix for sourness or fast shots. Start with distribution, dose and grind, then use the recipe and machine guide.', 'سجل موضع قياس الضغط ومرحلة القراءة مع وزن الناتج والوقت. لا تفك صمامات الضغط أو تغيّرها اعتمادًا على رقم تسويقي.', 'Record where and when pressure is measured, plus yield and time. Do not adjust internal pressure valves based on a marketing number.', 'Barista Hustle — What does 9 bars mean?', 'https://www.baristahustle.com/lesson/6-01-what-does-9-bars-mean/', '[]'::jsonb, 70, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('preinfusion', 'equipment', 'الترطيب المسبق', 'Preinfusion', 'الترطيب المسبق يبلل قرص الإسبريسو قبل مرحلة الضغط الأساسية. تختلف الآلية بين ضغط الشبكة والتحكم بالمضخة وأجهزة الذراع. سجّل زمن الترطيب وكيف تحسب الوقت الكلي، ولا تنقل ثواني جهاز إلى آخر كأنهما نفس العملية.', 'Preinfusion wets the espresso puck before the main pressure phase. Line-pressure, pump-controlled and lever machines do this differently. Record preinfusion duration and your shot-time convention rather than copying seconds between unlike systems.', 'قارن مع تثبيت الجرعة والناتج والتوزيع. إذا تغير التدفق، أعد ضبط الطحن وتذوق بدل الحكم من وقت الشوت وحده.', 'Compare with dose, yield and distribution fixed. If flow changes, redial grind and taste rather than judging shot time alone.', 'Barista Hustle — Preinfusion', 'https://www.baristahustle.com/lesson/ae-6-07-preinfusion/', '[]'::jsonb, 100, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('puck-prep', 'equipment', 'التوزيع والكبس وWDT', 'Distribution, tamping and WDT', 'ابدأ بسلة نظيفة وجافة وجرعة مناسبة لها، وفك التكتلات ووزع البن بالتساوي ثم اكبس بشكل مستوٍ ومتكرر. WDT أداة لتوزيع الطحن، وليس بديلًا عن ضبط الجرعة والطاحونة. زيادة قوة الكبس بلا نهاية لا تصلح استخلاصًا غير متجانس.', 'Use a clean, dry basket and a suitable dose. Break clumps, distribute evenly and tamp level and consistently. WDT helps distribute grounds but does not replace correct dose and grind. Ever-harder tamping does not fix uneven extraction.', 'كرر نفس الروتين قبل تعديل الطحن. تجنب طرق البورتافلتر بعد الكبس إذا كان يسبب تشققات أو انفصال القرص عن الحافة.', 'Repeat the same preparation before changing grind. Avoid post-tamp knocks that crack the puck or separate it from the basket wall.', 'Barista Hustle — Good puck preparation', 'https://www.baristahustle.com/lesson/ae-3-01-the-importance-of-good-puck-prep/', '[]'::jsonb, 90, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('channeling', 'equipment', 'التشانلنج وعدم تجانس الاستخلاص', 'Channeling and uneven extraction', 'التشانلنج مرور الماء عبر مناطق أسهل داخل قرص البن. الرش والتدفق غير المتجانس إشارات ممكنة، لكن غيابها لا يثبت التجانس. راجع التكتلات والجرعة المناسبة للسلة والكبس المستوي والنظافة قبل تجربة طحن أنعم بكثير.', 'Channeling means water follows easier paths through the puck. Spraying and uneven flow can be clues, but their absence does not prove even extraction. Check clumps, basket dose, level tamping and cleanliness before making the grind much finer.', 'صور التدفق تساعد، لكنها لا تقيس الاستخلاص وحدها. قارن الطعم وتكرار الوزن والوقت بعد تغيير خطوة واحدة من تجهيز القرص.', 'Flow images help but do not measure extraction on their own. Compare taste and repeatability after changing one puck-preparation step.', 'Barista Hustle — Channeling', 'https://www.baristahustle.com/lesson/ae-8-04-what-causes-channelling/', '[]'::jsonb, 105, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('basket-dose', 'equipment', 'السلة والبورتافلتر والجرعة', 'Basket, portafilter and dose', 'اختر جرعة تناسب سعة السلة ونوع البن؛ زيادة الجرعة قد تقلل المساحة فوق القرص. مقاس 58 mm لا يضمن توافق كل سلة أو تامبر أو بورتافلتر. السلة المضغوطة وغير المضغوطة تعملان بشكل مختلف، فراجع ملحقات الموديل.', 'Choose a dose suited to the basket and coffee; overdosing can reduce headspace. A 58 mm label does not guarantee that every basket, tamper or portafilter fits. Pressurized and nonpressurized baskets work differently, so check model compatibility.', 'إذا كانت الجرعة ثابتة وتحتاج تعديل النكهة، غيّر الناتج أو الطحن أولًا بحسب الوصفة بدل ملء السلة فوق طاقتها.', 'With dose fixed, adjust yield or grind according to the recipe instead of overfilling the basket.', 'Barista Hustle — Espresso dose', 'https://www.baristahustle.com/espresso-recipes-analyzing-dose/', '[]'::jsonb, 75, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('machine-cleaning', 'equipment', 'تنظيف الماكينة والعناية', 'Machine cleaning and maintenance', 'نظف السلة والبورتافلتر وأداة التحضير، وامسح عصا البخار بعد الاستعمال وفق الدليل. تنظيف زيوت البن يختلف عن إزالة التكلس. الباك فلاش يحتاج جهازًا يسمح به؛ لا تطبقه على كل ماكينة، ولا تستخدم مزيل تكلس أو منظفًا غير معتمد للموديل.', 'Clean the basket, portafilter and brewer, and wipe the steam wand after use as instructed. Removing coffee oils differs from descaling. Backflushing is only for compatible machines; use model-approved cleaning agents and procedures.', 'اتبع تنبيه الجهاز وجدول دليله، وسجل تاريخ تبديل الفلتر والتنظيف. تسريب الماء أو ضعف البخار المستمر يحتاج فحصًا بدل زيادة المنظف.', 'Follow machine reminders and its maintenance schedule. Record filter changes and cleaning. Persistent leaks or weak steam need inspection rather than more detergent.', 'Breville — Barista Express cleaning', 'https://www.breville.com/en-au/my-products/producthub/bes870/cleaning-guides/how-to-perform-a-cleaning-cycle', '[]'::jsonb, 65, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('scales', 'equipment', 'ميزان القهوة ووزن الناتج', 'Scales and brew measurements', 'زن البن وماء الترشيح أو ناتج الإسبريسو بالغرام، وصفر وزن الوعاء أولًا. تأخر قراءة الميزان قد يسبب تجاوز الناتج، لذلك راقب سلوك ميزانك. المعايرة تحتاج وزنًا مرجعيًا وطريقة الشركة، وحماية الماء تختلف بين الموازين.', 'Weigh coffee and filter water or espresso yield in grams, and tare the container first. Display lag can cause overshooting, so learn your scale’s response. Calibration needs the manufacturer’s procedure and reference weight; water protection varies by scale.', 'سجل جرعة البن والناتج منفصلين. لا تستبدل وزن الإسبريسو بملليلترات الكريما؛ الحجم يتغير مع الغاز.', 'Record dose and beverage yield separately. Do not substitute crema volume in milliliters for espresso mass; gas changes the volume.', 'Acaia — Lunar manuals', 'https://acaia.co/pages/lunar', '[]'::jsonb, 70, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('kettles', 'equipment', 'الغلاية والتحكم بالصب', 'Kettles and pouring control', 'الفوهة الرفيعة تساعد على التحكم بمكان ومعدل الصب؛ لا تحدد جودة الماء. حرارة قاعدة الغلاية قد تختلف عن الماء عند البن بسبب النقل وفقد الحرارة. ثبّت كمية الماء والتسخين وارتفاع الصب عند مقارنة الطحن.', 'A gooseneck helps control pour position and flow; it does not determine water quality. Kettle temperature can differ from water reaching the grounds due to transfer and heat loss. Keep fill, preheating and pour height consistent when comparing grind.', 'اختر سعة تناسب وصفتك، ولا تتجاوز خط التعبئة. وظيفة حفظ الحرارة مفيدة لتكرار الصبات دون إعادة تسخين عشوائي.', 'Choose capacity for your recipe without exceeding the fill line. Temperature hold can help repeat pours without inconsistent reheating.', 'Fellow — Stagg EKG', 'https://fellowproducts.com/products/stagg-ekg-electric-pour-over-kettle', '[]'::jsonb, 65, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('filters', 'equipment', 'الفلاتر وشكل القطّارة', 'Filters and dripper shape', 'شكل القطارة والفلتر ومقاسه يغيّر التدفق ومرور الزيوت والجسيمات. استخدم ورقًا يناسب أداتك ورتبه حسب الدليل؛ اختلاف الورق قد يحتاج إعادة ضبط الطحن. شطف الورق والتسخين يتبعان الوصفة والمصنع.', 'Dripper geometry and filter material and size affect flow and the passage of oils and particles. Use a compatible filter and position it as instructed. Changing paper can require redialing grind. Rinsing and preheating depend on the recipe and manufacturer.', 'قارن نوعَي ورق بنفس البن والجرعة والصبات. سجل زمن النزول والطعم بدل افتراض أن الأسرع أفضل.', 'Compare two papers with the same coffee, dose and pours. Record drawdown and taste rather than assuming faster is better.', 'CAFEC — Filter paper', 'https://cafec-jp.com/products/filterpaper/', '[]'::jsonb, 65, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('extraction', 'brewing', 'الاستخلاص والطعم', 'Extraction and taste', 'الاستخلاص ما يأخذه الماء من البن. نقصه قد يعطي كوبًا حادًا أو قليل الحلاوة، وعدم التجانس قد يجمع حموضة ومرارة. هذه إشارات وليست تشخيصًا وحيدًا؛ البن والتحميص والماء يؤثرون أيضًا. غيّر عاملًا واحدًا وسجل الطعم.', 'Extraction is what water removes from coffee. Too little can taste sharp or lack sweetness; uneven extraction can mix sour and bitter sensations. These are clues rather than a unique diagnosis: coffee, roast and water also matter. Change one variable and record taste.', 'ابدأ بوصفة موثقة، ثم قارن تعديلًا صغيرًا في الطحن مع تثبيت الجرعة والنسبة. أعطني الطريقة والأوزان والوقت إذا أردت ضبط كوبك.', 'Start from a sourced recipe. Compare a small grind adjustment with dose and ratio fixed. Supply method, weights and time for brew coaching.', 'Barista Hustle — Extraction and taste', 'https://www.baristahustle.com/coffee-extraction-and-how-to-taste-it/', '[]'::jsonb, 70, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('strength', 'brewing', 'التركيز مقابل الاستخلاص', 'Strength versus extraction', 'التركيز نسبة المواد الذائبة في المشروب، والاستخلاص نسبة ما أُخرج من البن. زيادة ناتج الإسبريسو تمرر ماء أكثر وقد تزيد الاستخلاص لكنها تخفف التركيز. TDS ماء التحضير ليس TDS القهوة. التخفيف بعد التحضير يقلل التركيز دون إعادة استخلاص البن.', 'Strength is the dissolved-solids concentration in the beverage; extraction is the fraction removed from the grounds. More espresso yield passes more water and can increase extraction while reducing strength. Brew-water TDS is not beverage TDS. Adding water afterward reduces strength without extracting the grounds again.', 'للنسبة الحسابية أعطني الجرعة والناتج. قياس نسبة الاستخلاص يحتاج وزن المشروب وقراءة TDS مناسبة للقهوة، ولا يستنتج من وقت الشوت وحده.', 'Give dose and yield for a ratio calculation. Extraction-yield measurement needs beverage mass and a suitable coffee TDS reading; shot time alone cannot determine it.', 'Barista Hustle — Understanding yield', 'https://www.baristahustle.com/espresso-recipes-understanding-yield/', '[]'::jsonb, 85, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('brewing-temperature', 'brewing', 'حرارة ماء التحضير', 'Brewing water temperature', 'حرارة الماء تؤثر في سرعة الاستخلاص وتختلف حاجتها حسب البن والطريقة. ابدأ بحرارة الوصفة المنشورة، وثبّت التسخين والصب ثم قارن تعديلًا صغيرًا. حرارة شاشة الجهاز أو الغلاية ليست بالضرورة حرارة الماء في قرص البن.', 'Water temperature influences extraction speed, with effects depending on coffee and method. Start with the published recipe temperature, keep preheating and pouring fixed and compare a small change. A display reading is not necessarily the temperature at the coffee bed.', 'لا تعالج المرارة بالحرارة وحدها؛ راجع التحميص والطحن والتجانس. وحرارة التحضير تختلف عن حرارة الشرب المناسبة.', 'Do not treat bitterness through temperature alone; check roast, grind and evenness. Brewing temperature and drinking temperature are different.', 'NCA — Pour-over brewing', 'https://www.aboutcoffee.org/brewing/pour-over-coffee/', '[]'::jsonb, 60, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('milk', 'brewing', 'الحليب والتبخير', 'Milk and steaming', 'التبخير يجمع إدخال الهواء وتسخين الحليب وصنع دوامة لتوزيع الفقاعات. ابدأ بحليب بارد وكمية مناسبة للإبريق، ونظف عصا البخار حسب دليل الجهاز. الحليب النباتي يختلف في البروتين والتركيب؛ النسخ المخصصة للباريستا قد تعطي رغوة أكثر استقرارًا.', 'Steaming combines aeration, heating and circulation to distribute bubbles. Start with cold milk and a suitable pitcher fill, and clean the wand as instructed. Plant milks differ in protein and composition; barista formulations may foam more consistently.', 'الرغوة الكبيرة قد تعني إدخال هواء زائد أو ضعف الدوامة. غيّر موضع العصا قليلًا داخل حدود الدليل، ولا تعاود تبخير الحليب مرارًا.', 'Large bubbles can indicate excess air or poor circulation. Adjust wand position within the manual’s guidance, and avoid repeatedly resteaming milk.', 'Breville — Microfoam milk', 'https://www.breville.com/au/en/coffee-journey/tutorials/espresso-tutorials/microfoam-milk.html', '[]'::jsonb, 80, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-stages', 'roasting', 'مراحل التحميص من الأخضر إلى البني', 'Roast stages: green to brown', 'البن الأخضر مادة البداية وليس درجة تحميص. أثناء التسخين يصفرّ ثم يتحول إلى البني، وتتطور الروائح. الفرقعة الأولى حدث مسموع، يليها التطوير حتى إنزال البن والتبريد. سجل اللون والرائحة والصوت والمنحنى معًا؛ لا يوجد وقت أو حرارة نهاية واحدة لكل المكاين.', 'Green coffee is the raw starting material, not a roast level. Heating changes it toward yellow and then brown as aromas develop. First crack is an audible event, followed by development until drop and cooling. Record color, aroma, sound and the curve together; one endpoint time or temperature cannot fit every roaster.', 'للوصول لبني فاتح، استخدم حمصة مرجعية لمحمصتك وأنزل عند هدف لون وطعم مطور. للمتوسط أو الغامق عدّل نقطة النهاية تدريجيًا مع تبريد ثابت وتذوق مقارن.', 'For light brown, use a reference profile for your machine and a developed color-and-taste target. For medium or dark, adjust the endpoint gradually with consistent cooling and comparative tasting.', 'Mill City Roasters — Sensory cues', 'https://millcityroasters.com/blogs/coffee-articles/roastery-sensory-cues', '[]'::jsonb, 35, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('maillard', 'roasting', 'الاصفرار وتفاعل ميلارد', 'Yellowing and Maillard reactions', 'التحول من الأخضر إلى الأصفر ثم البني يساعد على متابعة الحمصة. تفاعلات ميلارد بين مركبات السكر والأحماض الأمينية تسهم في الروائح واللون البني. تقسيم الحمصة لمراحل أداة للتسجيل؛ التفاعلات تتداخل وليست مفاتيح تُفتح عند درجة ثابتة.', 'The shift from green toward yellow and brown helps track roasting. Maillard reactions involving sugars and amino compounds contribute aroma and browning. Roast phases are a recording framework; reactions overlap rather than switching on at a universal temperature.', 'سجل لحظة الاصفرار بمعيار واحد لكل دفعاتك، وقارن الرائحة واللون في نفس الإضاءة. لا تنقل العلامة الحرارية بين حساسَي محمصتين مختلفتين.', 'Use one yellowing criterion across your batches. Compare aroma and color under consistent light, without transferring sensor landmarks between different roasters.', 'SCA — Roast color and flavor', 'https://sca.coffee/sca-news/coffee-decoded-4-roast-color', '[]'::jsonb, 90, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('rate-of-rise', 'roasting', 'RoR ومنحنى التحميص', 'RoR and the roast curve', 'RoR معدل تغير قراءة الحرارة لكل دقيقة، وليس درجة التحميص. يتأثر بنوع الحساس والتنعيم وحجم الدفعة. الارتفاع أو الانخفاض المفاجئ يحتاج مراجعة الطاقة والهواء والقراءات، ولا يثبت عيبًا في الطعم وحده. قارن بيانات من نفس الحساس والجهاز.', 'RoR is the rate of temperature change per minute, not roast degree. Sensor type, smoothing and batch size affect it. Sudden changes warrant reviewing energy, airflow and readings, but alone do not prove a flavor defect. Compare data from the same sensor and roaster.', 'ثبّت إعداد تسجيل المنحنى وتنعيمه، وسجل تغييرات الطاقة والهواء مع الوقت. اربط النتيجة بتذوق البن بعد الراحة بدل مطاردة شكل منحنى مثالي.', 'Keep logging and smoothing settings consistent. Record timed energy and airflow changes, then relate the result to tasting after rest rather than pursuing an ideal-looking curve.', 'Aillio — R2 roasting controls', 'https://docs.aillio.com/bullet-r2/operation/roasting-with-r2/', '[]'::jsonb, 95, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-control', 'roasting', 'الطاقة والهواء وحجم الدفعة', 'Heat, airflow and batch size', 'التسخين المسبق والطاقة والهواء ووزن الدفعة تعمل معًا. الدرم يحتفظ بطاقة مختلفة عن محمصة الهواء، وحساس الهواء ليس حساس البن. ابدأ بنطاق الدفعة وإعدادات دليل الموديل، ثم غيّر عاملًا واحدًا وسجل أثره.', 'Preheat, power, airflow and batch mass interact. A drum retains energy differently from an air roaster, and air-temperature and bean-temperature sensors are not interchangeable. Start within the model’s batch range and documented settings, then change one variable and record its effect.', 'تحويل منحنى بين محمصتين يحتاج معرفة نوع الحساس والدفعة والتدفق. استخدمه كمرجع أحداث وطعم، لا كجدول درجات منسوخ.', 'Transferring a curve requires sensor, batch and airflow information. Use it as an event-and-flavor reference rather than a copied temperature schedule.', 'IKAWA — Controlling roast variables', 'https://www.ikawacoffee.com/wp-content/uploads/2021/04/How-to-roast-with-IKAWA.pdf', '[]'::jsonb, 80, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-color', 'roasting', 'قياس لون التحميص وAgtron', 'Measuring roast color and Agtron', 'صور الأخضر والبني الفاتح والمتوسط والغامق مرجع بصري فقط؛ الإضاءة والشاشة تؤثر فيه. أجهزة اللون مثل Agtron تقيس بعينة وطريقة معايرة محددة. سجل قياس الحبة الكاملة والمطحونة منفصلين، ولا تحوّل صورة جوال إلى قراءة مخبرية.', 'Pictures of green, light, medium and dark beans are visual references; lighting and screens alter appearance. Instruments such as Agtron require a specified sample and calibration procedure. Record whole-bean and ground measurements separately; a phone photo is not a laboratory reading.', 'اتبع دليل جهاز اللون في تحضير العينة والمعايرة، وثبّت الطحن ووقت القياس. رقم أو اسم اللون لا يقيس التطوير الداخلي أو جودة الطعم وحده.', 'Follow the color instrument’s preparation and calibration instructions, keeping grind and measurement timing consistent. Color names or numbers alone do not measure internal development or cup quality.', 'UC Davis research — Universal roast color curve', 'https://www.nature.com/articles/s41598-025-06601-w', '[]'::jsonb, 100, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-defects', 'roasting', 'عيوب التحميص وتشخيصها', 'Roast defects and diagnosis', 'بقع سوداء موضعية قد تشير إلى تلسيع، وأطراف متفحمة قد تشير إلى tipping. الطعم العشبي أو الجاف يحتاج فحص التطوير والتحضير معًا. لا تشخّص baked من طول الحمصة وحده. افحص العينة والمنحنى والماء ووصفة التذوق قبل تعديل الحرارة.', 'Localized dark spots can indicate scorching, while charred tips can indicate tipping. Grassy or drying cups need both roast and brewing checks. Roast duration alone cannot diagnose baking. Inspect the sample, curve, water and tasting recipe before changing heat.', 'قارن دفعة مرجعية بنفس البن والماء، وافحص حبات كاملة ومطحونة. عدّل الطاقة أو نقطة النهاية مرة واحدة ثم أعد التذوق.', 'Compare a reference batch with the same coffee and water, inspecting whole and ground beans. Change energy or endpoint once, then taste again.', 'Mill City Roasters — Heat defects', 'https://millcityroasters.com/blogs/coffee-articles/roastery-sensory-cues', '[]'::jsonb, 100, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-cooling', 'roasting', 'التبريد والقشور والعناية بالمحمصة', 'Cooling, chaff and roaster care', 'بعد الإنزال، التبريد يحد من استمرار أثر الحرارة. نظف مجمع القشور ومسار الهواء حسب دليل المحمصة. لا توقف مراوح التبريد أو تفصل الجهاز الساخن بطريقة تخالف الدليل؛ بقايا القشور والدخان تؤثر في التشغيل وتزيد مخاطر الحريق.', 'Cooling after drop limits continuing heat effects. Clean the chaff collector and airflow path as instructed. Do not stop cooling fans or disconnect a hot roaster contrary to its manual. Chaff and smoke residue affect operation and increase fire risk.', 'سجل مدة التبريد ودرجة النهاية إن كانت مقاسة. ثبت طريقة التبريد قبل مقارنة نقطتي إنزال، واتبع إجراءات الشركة لأي دخان غير طبيعي.', 'Record cooling duration and final temperature when measured. Keep cooling consistent while comparing drop endpoints, and follow manufacturer procedures for abnormal smoke.', 'Aillio — R2 maintenance', 'https://docs.aillio.com/bullet-r2/operation/maintaining-the-r2/', '[]'::jsonb, 95, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('development-time', 'roasting', 'الفرقعة ووقت التطوير وDTR', 'First crack, development and DTR', 'وقت التطوير في تسجيل الحمصة هو الفترة من بداية الفرقعة الأولى المسجلة إلى الإنزال. DTR = وقت التطوير ÷ الوقت الكلي × 100. نفس النسبة لا تعني نفس اللون أو الطعم، ولا توجد نسبة سحرية لكل بن. سجل معيار سماع الفرقعة ومكان حساس الحرارة.', 'Recorded development time runs from the marked start of first crack to drop. DTR = development time ÷ total time × 100. Equal ratios do not imply equal color or flavor, and no universal magic ratio exists. Record your crack criterion and temperature-sensor location.', 'مثال حسابي: فرقعة عند 8:00 وإنزال عند 10:00 تعطي تطوير دقيقتين وDTR ‏20%. المثال يشرح الحساب ولا يوصي بهذه النهاية.', 'Arithmetic example: first crack at 8:00 and drop at 10:00 gives two minutes of development and 20% DTR. This explains calculation without recommending that endpoint.', 'Münchow & Alstrup — Time and color study', 'https://www.roastmagazine.com/stories/flavor-development-the-relationship-between-time-and-color-in-coffee-roasting', '[]'::jsonb, 100, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('flavor-notes', 'sensory', 'الإيحاءات والرائحة والقوام', 'Flavor notes, aroma and texture', 'الإيحاءات وصف لما يذكّرنا به الكوب، وليست دليلًا على إضافة فاكهة أو شوكولاتة. افصل الرائحة والطعم والحموضة والمرارة والقوام والأثر اللاحق. معجم World Coffee Research يقدم أوصافًا ومراجع حسية؛ وصف النكهة يختلف عن تقييم تفضيلك الشخصي.', 'Flavor notes describe what a cup reminds us of; they do not establish that fruit or chocolate was added. Separate aroma, flavor, acidity, bitterness, texture and aftertaste. World Coffee Research provides sensory descriptors and references; describing flavor differs from rating your preference.', 'ابدأ بفئة عامة مثل فاكهي أو مكسرات، ثم وصف أدق إذا تكرر إحساسك. تذوق الكوب وهو يبرد ودوّن الشدة بدل مطاردة كلمة العبوة.', 'Start with a broad family such as fruit or nuts, then narrow it if the sensation repeats. Taste as the cup cools and record intensity rather than chasing the bag label.', 'World Coffee Research — Sensory lexicon', 'https://worldcoffeeresearch.org/resources/sensory-lexicon', '[]'::jsonb, 75, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('cupping', 'sensory', 'التذوق المقارن والكَبِنغ', 'Comparative tasting and cupping', 'التذوق المقارن يحتاج نفس الماء والجرعة والطحن والحرارة والزمن. رمّز العينات لتقليل تأثير الاسم، وقارنها في أكثر من درجة حرارة. افصل وصف ما تذوقته عن إعجابك به؛ نظام CVA لدى SCA يميز التقييم الوصفي عن الانطباع عن الجودة.', 'Comparative tasting requires consistent water, dose, grind, temperature and time. Code samples to reduce label bias and compare at several temperatures. Separate observed descriptors from liking; the SCA’s CVA separates descriptive assessment from quality impressions.', 'كرر المقارنة ولا تعتبر كوبًا واحدًا نتيجة علمية قاطعة. سجل الاختلافات والظروف، وارجع للبروتوكول الرسمي إن أردت تقييمًا مهنيًا.', 'Repeat the comparison rather than treating one cup as conclusive research. Record differences and conditions; use the official protocol for professional assessment.', 'SCA — CVA standards', 'https://sca.coffee/sca-news/sca-new-cva-cupping-standards-7ga28', '[]'::jsonb, 90, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('v60-technique', 'brewing', 'طريقة تحضير V60 خطوة بخطوة', 'V60 technique step by step', 'دليل هاريو للـV60 مقاس 02: اشطف الفلتر الورقي بماء ساخن ثم فرّغ الكوب؛ الشطف يقلل طعم الورق. ضع 15 غرام بن مطحون للفلتر، والهدف 250 غرام ماء. اغلِ الماء واتركه يهدأ قليلًا؛ مع ميزان حرارة استهدف 92–96°م. اسكب صبة سريعة تبلل كل البن وانتظر نحو 30 ثانية (البلوم)، ثم أكمل الصب ببطء في دوائر صغيرة حتى يقرأ الميزان 250 غرام، واتركه يصفّى؛ الدليل يذكر نحو دقيقتين ونصف. هذه نقطة بداية من هاريو وليست قاعدة لكل بن.', 'Hario’s guide for the V60 02: rinse the paper filter with hot water and empty the mug; rinsing reduces papery taste. Add 15 g of coffee ground for filter and aim for 250 g of water. Boil the kettle and let it cool briefly; with a thermometer aim for 92–96°C. Make one quick pour that wets all the grounds and wait about 30 seconds (the bloom), then pour slowly in small circles until the scale reads 250 g and let it drain; the guide mentions around two and a half minutes. This is Hario’s starting point, not a rule for every coffee.', 'ثبّت 15 غرام و250 غرام ماء وغيّر الطحن فقط بين كوبين: إذا كان الطعم حامضًا وفارغًا اطحن أنعم قليلًا، وإذا كان مرًّا وجافًّا اطحن أخشن. سجّل وقت التصفية مع كل كوب حتى تقارن.', 'Hold 15 g and 250 g fixed and change only grind between two cups: if the taste is sour and empty grind slightly finer; if it is bitter and drying grind coarser. Record the drain time with each cup so you can compare.', 'Hario UK — V60 brew guide', 'https://www.hario.co.uk/pages/brew-guides-v60-intermediate', '[{"title":"Barista Hustle — Coffee extraction: the 80:20 method","url":"https://www.baristahustle.com/coffee-extraction-the-80-20-method/"}]'::jsonb, 112, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('brew-ratio', 'brewing', 'نسبة البن إلى الماء في الترشيح', 'Coffee-to-water ratio for filter', 'النسبة هي وزن البن إلى وزن الماء. الجمعية الوطنية الأمريكية للقهوة (NCA) تذكر للبور أوفر غرامًا واحدًا من البن لكل 13 إلى 16 غرام ماء (1:13 إلى 1:16)، وتنصح بوزن البن والماء بالغرام لا بالملاعق. تذكر أيضًا حرارة تحضير 93±3°م، وتلامسًا بين البن والماء من دقيقتين إلى أربع، وبلومًا بماء يساوي ضعف وزن البن مع انتظار 30–45 ثانية. النسبة الأصغر تعطي كوبًا أقوى، والأكبر كوبًا أخف.', 'A brew ratio is the weight of coffee to the weight of water. For pour-over, the National Coffee Association (NCA) gives 1 gram of coffee to 13–16 grams of water (1:13 to 1:16) and advises weighing both in grams, not spoons. It also gives a brewing temperature of 93 ± 3°C, two to four minutes of contact between coffee and water, and a bloom using water equal to double the coffee weight with a 30–45 second wait. A smaller ratio gives a stronger cup; a larger one gives a lighter cup.', 'جرّب نفس البن بنسبة 1:15 ثم 1:16 مع تثبيت الطحن والحرارة، وتذوّق الكوبين جنبًا إلى جنب. اكتب «احسب 18 غرام بنسبة 1:16» وأحسب لك كمية الماء.', 'Brew the same coffee at 1:15 and then 1:16 with grind and temperature fixed, and taste the two cups side by side. Type “Calculate 18 g at 1:16” and I will work out the water.', 'NCA — Pour-over coffee', 'https://www.aboutcoffee.org/brewing/pour-over-coffee/', '[]'::jsonb, 88, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('pour-agitation', 'brewing', 'الصب والتحريك وتدوير القطّارة', 'Pouring, agitation and the swirl', 'التحريك يغيّر الاستخلاص. «راو سبن» هو تدوير القطّارة أثناء التحضير حتى يدور الخليط؛ يقول سكوت راو إنه يقلل التشانلنج في التصفية الأخيرة ويترك طبقة بن مستوية. التدوير يحرّك كل الطبقة معًا، بينما التقليب بالملعقة قد يترك أجزاء دون تحريك. لكن التدوير القوي قد يسد الفلتر ويبطئ التصفية ويعطي قبضًا. ارتفاع الصب مهم أيضًا: الصب المنخفض جدًا لا يحرّك البن كفاية، والمرتفع جدًا قد يسد الورق؛ الارتفاع المناسب يختلف من بن لآخر ويُعرف بالتجربة.', 'Agitation changes extraction. The “Rao spin” is swirling the dripper during brewing so the slurry spins; Scott Rao says it minimizes channeling in the final drawdown and leaves a flat bed. Swirling agitates the whole bed at once, while stirring can leave parts undisturbed. Swirling too hard, however, can clog the filter, slow the drawdown and make the brew astringent. Pour height matters too: too low does not stir the bed enough, too high risks clogged paper; the right height differs for each coffee and is found by trial and error.', 'اختر طريقة تحريك واحدة وكررها بنفس القوة في كل كوب. قارن كوبًا بتدويرة خفيفة واحدة بعد آخر صبة بكوب دون تدوير، وسجّل وقت التصفية والطعم.', 'Pick one agitation method and repeat it with the same force every brew. Compare one gentle swirl after the last pour against no swirl, recording drain time and taste.', 'Barista Hustle — The Rao Spin', 'https://www.baristahustle.com/the-rao-spin/', '[{"title":"Barista Hustle — The yo-yo pour","url":"https://www.baristahustle.com/post-yo-yo-pour/"}]'::jsonb, 105, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('drawdown', 'brewing', 'بطء التصفية وانسداد الفلتر', 'Slow drawdown and filter clogging', 'إذا صار نزول الماء بطيئًا جدًا في البور أوفر فالسبب غالبًا الفاينز: جسيمات دقيقة تسد ثقوب الورق حتى توقف التدفق أحيانًا. لذلك البور أوفر حساس للطواحين التي تنتج فاينز كثيرة، أما الورق نفسه فمقاومته قليلة. التحريك القوي، مثل تقليب البلوم، يدفع الفاينز إلى الفلتر. باريستا هَسل تقترح بلومًا بوزن ضعفين إلى ثلاثة أضعاف البن: القليل يترك كتلًا جافة، والكثير يزيد خطر الانسداد.', 'When pour-over drawdown becomes very slow, fines are the usual cause: tiny particles lodge in the paper’s holes and can even stop the flow. Pour-over is therefore sensitive to grinders that produce excess fines, while the paper itself adds little resistance. Strong agitation, such as stirring the bloom, drives fines into the filter. Barista Hustle suggests a bloom of two to three times the coffee weight: too little leaves dry clumps, too much raises the risk of clogging.', 'إذا تكرر الانسداد: خفف التحريك أولًا، ثم اطحن أخشن درجة واحدة، وقارن وقت التصفية. غيّر عاملًا واحدًا في كل مرة.', 'If clogging repeats: reduce agitation first, then grind one step coarser, and compare drain times. Change one variable at a time.', 'Barista Hustle — Blooming and clogging', 'https://www.baristahustle.com/blooming-and-clogging/', '[{"title":"Barista Hustle — Percolation: grind","url":"https://www.baristahustle.com/lesson/p-2-04-grind/"}]'::jsonb, 106, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('taste-direction', 'brewing', 'اتجاه التعديل: استخلاص أكثر أم أقل', 'Which way to adjust: extract more or less', 'القهوة ناقصة الاستخلاص توصف بأنها حامضة وفارغة، والزائدة الاستخلاص بأنها مرّة وجافة. لتستخلص أكثر: اطحن أنعم أو أطل وقت التحضير أو استخدم ماء أكثر. لتستخلص أقل: اطحن أخشن أو قصّر الوقت أو استخدم ماء أقل. ثبّت وزن البن طوال التجربة حتى تعرف أثر كل تعديل. بوصلة القهوة من باريستا هَسل تعمل بنفس المنطق: تذوّق، حدّد الطعم السلبي، ثم عدّل نحو المركز وكرر؛ وهي لا تنطبق على الإسبريسو.', 'Under-extracted coffee is described as sour and empty; over-extracted coffee as bitter and drying. To extract more: grind finer, brew longer, or use more water. To extract less: grind coarser, brew shorter, or use less water. Keep the coffee dose the same throughout so each change can be read. Barista Hustle’s Coffee Compass follows the same logic: taste, find the negative flavor, adjust back toward the center and repeat; it does not apply to espresso.', 'اكتب لي قياسات كوبك: الجرعة والماء والوقت والطعم، وأقترح تعديلًا واحدًا. لا تغيّر الطحن والنسبة معًا في نفس الكوب.', 'Give me your cup’s measurements: dose, water, time and taste, and I will suggest one change. Do not change grind and ratio in the same brew.', 'Barista Hustle — Coffee extraction: the 80:20 method', 'https://www.baristahustle.com/coffee-extraction-the-80-20-method/', '[{"title":"Barista Hustle — The Coffee Compass","url":"https://www.baristahustle.com/coffee-compass/"}]'::jsonb, 40, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('aeropress', 'brewing', 'الإيروبرس: الطريقة الرسمية', 'AeroPress: the official method', 'تعليمات إيروبرس للموديل الأساسي: ضع مغرفة ممتلئة أو 16–18 غرام بن متوسط الطحن، وسخّن الماء إلى 85°م واملأ حتى العلامة 4. حرّك بلطف نحو 3 ثوانٍ، ثم انتظر 60 ثانية للطحن المتوسط أو 30 ثانية للمتوسط الناعم. اضغط بضغط لطيف وثابت حتى يبدأ صوت الهسهسة وينتهي. الشركة تقترح 80°م للتحميص الغامق و85°م للمتوسط والفاتح، وتذكر أن الضغط الهادئ يأخذ 20 إلى 40 ثانية.', 'AeroPress instructions for the standard model: add one heaping scoop or 16–18 g of medium-ground coffee, heat water to 85°C (185°F) and fill to the 4 mark. Stir gently for about 3 seconds, then wait 60 seconds for a medium grind or 30 seconds for medium-fine. Press with gentle, constant pressure until the hissing sound begins and ends. The company suggests 80°C for dark roasts and 85°C for medium and light roasts, and says slow, gentle pressing takes 20 to 40 seconds.', 'هزّ الحجرة لتسوية البن قبل الصب. إذا صار الضغط صعبًا فالطحن أنعم من اللازم؛ اطحن أخشن قليلًا بدل زيادة القوة.', 'Shake the chamber to level the bed before pouring. If pressing becomes hard the grind is too fine; go slightly coarser rather than pushing harder.', 'AeroPress — Welcome guide', 'https://aeropress.com/pages/welcome', '[{"title":"AeroPress — FAQ","url":"https://aeropress.com/pages/faq"}]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('chemex', 'brewing', 'الكيمكس: تعليمات الشركة', 'Chemex: the maker’s instructions', 'تعليمات كيمكس: اطحن البن طحنًا متوسطًا مائلًا للخشن. افتح الفلتر واجعل الجهة السميكة ذات الثلاث طبقات فوق مجرى الصب؛ هذه الطبقات تمنع الفلتر من الانهيار داخل المجرى الذي يعمل كقناة هواء. اغلِ الماء ثم ارفعه عن النار حتى يهدأ الغليان. بلّل البن بقليل من الماء بحركة دائرية وانتظر نحو 30 ثانية للبلوم، ثم أكمل الصب ببطء مع إبقاء الماء تحت الحافة. الطحن الخشن جدًا يصفّي بسرعة، والناعم جدًا يسد الفلتر.', 'Chemex instructions: grind to medium-coarse. Open the filter and place the thick three-layer side over the pouring spout; those layers keep the filter from collapsing into the spout, which acts as an air channel. Boil water, then take it off the heat until it stops boiling vigorously. Wet the grounds with a little water in a circular motion and wait about 30 seconds for the bloom, then keep pouring slowly with the water below the rim. Too coarse a grind filters too quickly; too fine clogs the filter.', 'الشركة لا تعطي نسبة بالغرام؛ ابدأ بنسبة البور أوفر التي تستخدمها، ووزن البن والماء، ثم عدّل الطحن بحسب سرعة التصفية والطعم.', 'Chemex gives no gram ratio; start from the pour-over ratio you already use, weigh coffee and water, then adjust grind by drain speed and taste.', 'CHEMEX — Classic Series support', 'https://chemexcoffeemaker.com/pages/classic-series-product-support', '[{"title":"CHEMEX — FAQ","url":"https://chemexcoffeemaker.com/pages/faq"}]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('turkish-coffee', 'brewing', 'القهوة التركية', 'Turkish coffee', 'القهوة التركية مسجلة لدى اليونسكو في قائمة التراث الثقافي غير المادي منذ 2013. بحسب اليونسكو: يُطحن البن المحمص حديثًا حتى يصير مسحوقًا ناعمًا، ثم يُطبخ البن مع الماء البارد والسكر ببطء على الموقد حتى تتكون الرغوة المطلوبة. تُقدّم في فناجين صغيرة مع كأس ماء. وهي رمز للضيافة والصداقة، وتحضر في الخطوبة والأعياد، وتنتقل معرفتها داخل الأسرة.', 'Turkish coffee has been on UNESCO’s Representative List of Intangible Cultural Heritage since 2013. According to UNESCO: freshly roasted beans are ground to a fine powder, then the coffee, cold water and sugar are brewed slowly on a stove to produce the desired foam. It is served in small cups with a glass of water. It symbolizes hospitality and friendship, features in engagement ceremonies and holidays, and its knowledge is passed on within families.', 'البن هنا لا يُفلتر، فاترك الفنجان لحظات حتى يستقر الراسب قبل الشرب. ثبّت كمية البن والماء وغيّر السكر فقط حتى تعرف ذوقك.', 'The coffee is not filtered, so let the cup settle briefly before drinking. Hold coffee and water fixed and vary only the sugar to find your taste.', 'UNESCO — Turkish coffee culture and tradition', 'https://ich.unesco.org/en/RL/turkish-coffee-culture-and-tradition-00645', '[]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('arabic-coffee', 'brewing', 'القهوة العربية وآداب تقديمها', 'Arabic coffee and its etiquette', 'القهوة العربية مسجلة لدى اليونسكو رمزًا للكرم، وتقديمها جزء مهم من الضيافة. يصف قرار اليونسكو لعام 2015 تحميص البن تحميصًا خفيفًا في مقلاة مسطحة على النار، ثم دقّه في هاون نحاسي. يُقدَّم الضيف الأهم أو الأكبر سنًّا أولًا، ويُملأ ربع الفنجان ثم يُعاد ملؤه. المعتاد شرب فنجان واحد على الأقل دون تجاوز ثلاثة. تُصب القهوة باليد اليمنى، ويهز الضيف الفنجان إشارةً إلى الاكتفاء.', 'Arabic coffee is inscribed by UNESCO as a symbol of generosity, and serving it is an important part of hospitality. UNESCO’s 2015 decision describes beans lightly roasted in a shallow pan over a fire, then pounded in a copper mortar. The most important or oldest guest is served first, filling a quarter of the cup, which can then be refilled. Common practice is to drink at least one cup but not exceed three. The coffee is poured with the right hand, and the guest shakes the cup to signal they have finished.', 'وصف اليونسكو يخص العادة والضيافة لا مقادير محددة؛ الإضافات مثل الهيل والزعفران تختلف من بيت لآخر ومن منطقة لأخرى. اسأل أهل الوصفة عن مقاديرهم وسجّلها.', 'UNESCO describes the custom and hospitality, not fixed measurements; additions such as cardamom and saffron vary by household and region. Ask the family whose recipe it is and record their amounts.', 'UNESCO — Arabic coffee, a symbol of generosity', 'https://ich.unesco.org/en/RL/arabic-coffee-a-symbol-of-generosity-02111', '[{"title":"UNESCO — Decision 10.COM 10.B.32","url":"https://ich.unesco.org/en/decisions/10.COM/10.B.32"}]'::jsonb, 110, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('espresso-basics', 'brewing', 'ما هو الإسبريسو؟', 'What is espresso?', 'الإسبريسو ليس نوع بن ولا درجة تحميص، بل مشروب سُمّي باسم طريقة تحضيره: ماء قريب من الغليان يُدفع بضغط عالٍ خلال بن مطحون ناعمًا. بحسب NCA يتلامس الماء والبن 20–30 ثانية، والنسبة غرام بن إلى غرامين مشروب (1:2)، والطحن ناعم مثل ملح الطعام، والشوت نحو أونصة وفيه قرابة 63 ملغ كافيين. لامارزوكو تذكر أن الماكينة تطبّق 9 بار. الطبقة العليا الذهبية البنية هي الكريما.', 'Espresso is not a type of bean or a roast; it is a drink named after its brewing method: near-boiling water forced at high pressure through finely ground coffee. According to the NCA, water and coffee are in contact for 20–30 seconds, the ratio is 1 gram of coffee to 2 grams of beverage (1:2), the grind is fine like table salt, and a shot is about one ounce with roughly 63 mg of caffeine. La Marzocco notes the machine applies 9 bars of pressure. The golden-brown top layer is the crema.', 'زِن الجرعة الداخلة والمشروب الخارج وسجّل الوقت في كل شوت. ابدأ بنسبة 1:2 ثم عدّل الطحن فقط حتى يتوازن الطعم.', 'Weigh the dose in and the beverage out and time every shot. Start at 1:2, then adjust only grind until the taste balances.', 'NCA — Espresso', 'https://www.aboutcoffee.org/brewing/espresso/', '[{"title":"La Marzocco Home — What is espresso?","url":"https://home.lamarzoccousa.com/what-is-espresso/"}]'::jsonb, 62, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('espresso-ratio', 'brewing', 'نسبة الإسبريسو: ريستريتو ونورمالي ولونغو', 'Espresso ratio: ristretto, normale and lungo', 'نسبة الإسبريسو هي وزن البن المطحون إلى وزن المشروب في الكوب. لامارزوكو تصنّف: من 1:1 إلى 1:2 ريستريتو، من 1:2 إلى 1:3 نورمالي، ومن 1:3 إلى 1:4 لونغو. وتذكر أن المقاهي المختصة تستخدم 16–19 غرام بن وتنتج 32–38 غرام مشروب. باريستا هَسل توضح الأثر: ناتج أكثر يعني استخلاصًا أعلى وتركيزًا أقل، وناتج أقل يعني استخلاصًا أقل وتركيزًا أعلى؛ لذلك قد يكون الريستريتو قويًّا وغنيًّا لكنه حامض وناقص الاستخلاص.', 'An espresso brew ratio is the weight of ground coffee to the weight of liquid espresso in the cup. La Marzocco classifies 1:1 to 1:2 as ristretto, 1:2 to 1:3 as normale, and 1:3 to 1:4 as lungo, and notes specialty shops use 16–19 g of coffee yielding 32–38 g. Barista Hustle explains the effect: more yield gives more extraction but lower strength; less yield gives less extraction but higher strength, which is why a ristretto can be strong and rich yet sour and under-extracted.', 'ثبّت الجرعة والطحن واسحب شوتين: واحد بنسبة 1:2 وآخر 1:2.5، وتذوّقهما معًا. سجّل الوزن لا الحجم؛ الكريما تخدع العين.', 'Hold dose and grind fixed and pull two shots: one at 1:2 and one at 1:2.5, then taste them together. Record weight, not volume; crema misleads the eye.', 'La Marzocco Home — Brew ratios around the world', 'https://home.lamarzoccousa.com/brew-ratios-around-world/', '[{"title":"Barista Hustle — Espresso recipes: understanding yield","url":"https://www.baristahustle.com/blog/espresso-recipes-understanding-yield/"}]'::jsonb, 108, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('crema', 'brewing', 'الكريما: ماذا تعني وماذا لا تعني', 'Crema: what it does and does not tell you', 'الكريما رغوة الإسبريسو، وأغلب حجمها غاز ثاني أكسيد الكربون. التحميص يحبس الغاز في الحبة، وتحت الضغط يخرج مع الماء فقاعات دقيقة تحيط بها المياه والزيوت. البن الأقدم يعطي كريما أقل لأن الغاز تسرّب مع الوقت، والتحميص الغامق جدًا يعطي كريما أكثر من الفاتح، والطحن الخشن يعطي أقل. لكن كمية الغاز لا ترتبط مباشرة بمركبات النكهة؛ الأفضل أن تثق بلسانك لا بعينك. لامارزوكو تذكر أن الكريما قد تكون مرّة وتنصح بتقليبها في الشوت.', 'Crema is espresso’s foam, and by volume it is mostly carbon dioxide. Roasting traps the gas in the bean; under pressure it comes through with the water as microscopic bubbles surrounded by water and oils. Older beans give less crema because gas has escaped over time, a very dark roast gives much more than a light one, and a coarse grind gives less. But the amount of gas has no direct connection to flavor compounds; trust your tongue rather than your eyes. La Marzocco notes crema can taste bitter and suggests stirring it into the shot.', 'لا تحكم على الشوت من لون الكريما. تذوّق شوتًا بعد تقليبه وآخر دون تقليب من نفس الضبط، ولاحظ الفرق في المرارة.', 'Do not judge a shot by crema color. Taste one shot stirred and one unstirred from the same settings and notice the difference in bitterness.', 'Clive Coffee — What is espresso crema?', 'https://clivecoffee.com/blogs/learn/what-is-espresso-crema', '[{"title":"La Marzocco Home — What is espresso?","url":"https://home.lamarzoccousa.com/what-is-espresso/"}]'::jsonb, 105, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('espresso-taste', 'brewing', 'ضبط الإسبريسو بالطعم: حامض أم مر', 'Dialing espresso by taste: sour or bitter', 'في دليل كلايف كوفي: الشوت الحامض ناقص الاستخلاص وعلاجه طحن أنعم؛ عدّل تعديلًا صغيرًا ثم اسحب شوتًا جديدًا وكرر حتى يتوازن. إذا صار مرًّا فقد تجاوزت؛ ارجع تعديلًا بسيطًا نحو الأخشن. أبقِ الناتج المستهدف ثابتًا وأنت تعدّل الطحن، فإذا كان هدفك 40 غرام فابقَ عليه. وإذا كان شوت 1:2 شديد الحدة فزد الناتج. باريستا هَسل تنبّه أن الطحن الأنعم فالأنعم لا يزيد الاستخلاص بلا حد، وأن الشوت المر والحامض والخفيف معًا علامة استخلاص غير متجانس.', 'In Clive Coffee’s guide: a sour shot is under-extracted and the fix is a finer grind; make a small adjustment, pull another shot and repeat until balanced. If it turns bitter you went too far; make a slight adjustment back toward coarse. Keep the target yield constant while adjusting grind: if you are aiming for 40 g, stay at 40 g. If a 1:2 shot tastes too intense, increase the yield. Barista Hustle cautions that grinding finer and finer does not keep raising extraction, and that a shot that is bitter, sour and weak at once signals uneven extraction.', 'اكتب لي الجرعة والناتج والوقت والطعم وأقترح تعديلًا واحدًا. إذا اجتمع المر والحامض راجع التوزيع والكبس قبل تغيير الطحن.', 'Give me dose, yield, time and taste and I will suggest one change. If bitter and sour appear together, review distribution and tamping before changing grind.', 'Clive Coffee — Dialing in espresso by taste', 'https://clivecoffee.com/blogs/learn/dialing-in-espresso-by-taste', '[{"title":"Barista Hustle — The Espresso Compass","url":"https://www.baristahustle.com/blog/the-espresso-compass/"}]'::jsonb, 45, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('espresso-drinks', 'brewing', 'مشروبات الإسبريسو: أمريكانو وكورتادو وفلات وايت', 'Espresso drinks: americano, cortado and flat white', 'بحسب دليل لامارزوكو: الأمريكانو إسبريسو مخفف بماء ساخن، والمعتاد شوت مزدوج مع نحو 8 أونصات ماء. الماكياتو إسبريسو «مبقّع» بقليل من رغوة الحليب. الكورتادو مقادير متساوية من الإسبريسو والحليب المبخّر. الفلات وايت إسبريسو مع حليب مبخّر ورغوة ناعمة رقيقة لا تتجاوز نحو نصف سنتيمتر. الكابتشينو الإيطالي التقليدي ثلث إسبريسو وثلث حليب وثلث رغوة. اللاتيه أكبرها حجمًا وأخفها طعم قهوة.', 'According to La Marzocco’s guide: an americano is espresso diluted with hot water, typically a double shot with about 8 oz of water. A macchiato is espresso “spotted” with a little milk foam. A cortado is equal parts espresso and steamed milk. A flat white is espresso with steamed milk and thin microfoam of no more than about half a centimetre. The classic Italian cappuccino is one-third espresso, one-third milk and one-third foam. A latte is the largest and the mildest in coffee taste.', 'الأسماء والمقاسات تختلف بين المقاهي والدول. اسأل المقهى عن حجم الكوب وعدد الشوتات بدل الاعتماد على الاسم وحده.', 'Names and sizes vary between cafés and countries. Ask the café for cup size and number of shots rather than relying on the name alone.', 'La Marzocco Home — The beginner’s guide to espresso drinks', 'https://home.lamarzoccousa.com/the-beginners-guide-to-espresso-drinks-2/', '[]'::jsonb, 86, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('caffeine', 'beans', 'الكافيين في القهوة والحد اليومي', 'Caffeine in coffee and the daily limit', 'هيئة الغذاء والدواء الأمريكية (FDA) تذكر أن 400 ملغ كافيين في اليوم، أي نحو كوبين إلى ثلاثة أكواب قهوة بحجم 12 أونصة، كمية لا ترتبط عادةً بآثار سلبية لدى معظم البالغين، مع اختلاف كبير في الحساسية بين الناس. كوب القهوة المفلترة بحجم 12 أونصة فيه 113–247 ملغ. الديكاف ليس خاليًا تمامًا: 2–15 ملغ في كوب 8 أونصات. علامات الزيادة: تسارع النبض، الأرق، القلق، الرجفة، اضطراب المعدة والصداع. الحامل والمرضع تستشيران الطبيب.', 'The U.S. FDA says 400 mg of caffeine a day, about two to three 12-fl-oz cups of coffee, is an amount not generally associated with negative effects for most adults, though sensitivity varies widely. A 12-fl-oz cup of brewed coffee contains 113–247 mg. Decaf is not caffeine-free: 2–15 mg per 8-fl-oz cup. Signs of too much include a faster heart rate, insomnia, anxiety, jitters, upset stomach and headache. People who are pregnant or breastfeeding should ask their health care provider.', 'هذه معلومات عامة وليست نصيحة طبية. إذا كانت لديك حالة صحية أو تتناول أدوية فاسأل طبيبك عن الكمية المناسبة لك.', 'This is general information, not medical advice. If you have a health condition or take medication, ask your doctor what amount suits you.', 'FDA — Spilling the beans: how much caffeine is too much?', 'https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much', '[]'::jsonb, 68, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('origins', 'beans', 'مناطق زراعة البن والارتفاع', 'Coffee growing regions and altitude', 'بحسب NCA يُزرع البن في نطاق مناخي ضيق حول خط الاستواء، بين مداري السرطان والجدي، في أكثر من 40 دولة. الظروف المثالية: تربة غنية، حرارة معتدلة، أمطار موسمية منتظمة وشمس مظللة. النكهة تعكس الصنف والأرض والارتفاع؛ في المرتفعات تساعد البرودة والظل على نمو أبطأ للحبة ونكهات أكثر تعقيدًا. أمثلة NCA: إثيوبيا فاكهية وزهرية، كينيا بحموضة فاكهية لامعة، البرازيل حلوة متوسطة القوام قليلة الحموضة، وإندونيسيا ترابية بقوام أثقل.', 'According to the NCA, coffee grows in a narrow climatic zone along the Equator, between the Tropics of Cancer and Capricorn, in more than 40 countries. Ideal conditions are rich soil, mild temperatures, regular seasonal rainfall and shaded sun. Flavor reflects variety, terroir and altitude; at higher altitude, cooler temperatures and shade allow slower bean development and more complex flavors. NCA examples: Ethiopia fruity and floral, Kenya bright fruity acidity, Brazil sweet, medium-bodied and low in acidity, Indonesia earthy with fuller body.', 'هذه أوصاف عامة؛ المزرعة والمعالجة والتحميص تغيّر الكوب كثيرًا. تذوّق بنّين من منشأين بنفس الوصفة وسجّل الفرق بنفسك.', 'These are generalizations; farm, processing and roasting change the cup a great deal. Taste two origins with the same recipe and note the difference yourself.', 'NCA — Coffee regions of the world', 'https://www.aboutcoffee.org/origins/coffee-regions-of-the-world/', '[]'::jsonb, 62, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('specialty', 'beans', 'ما معنى القهوة المختصة؟', 'What does specialty coffee mean?', 'جمعية القهوة المختصة (SCA) تعرّفها بأنها قهوة أو تجربة قهوة معروفة بصفاتها المميزة، ولهذه الصفات قيمة إضافية كبيرة في السوق. الصفات داخلية مثل النكهة والرائحة والقوام، وخارجية مثل المنشأ والمنتج وطرق الزراعة والمعالجة. التعريف يتجاوز درجة واحدة أو وصف طعم واحد. تقليديًّا استُخدمت استمارة من 100 نقطة وعُدّت القهوة مختصة إذا تجاوزت 80، ثم استبدلتها SCA بنظام تقييم القيمة (CVA).', 'The Specialty Coffee Association (SCA) defines it as a coffee or coffee experience recognized for its distinctive attributes, which give it significant extra value in the marketplace. Attributes are intrinsic, such as flavor, aroma and mouthfeel, and extrinsic, such as origin, producer, growing practices and processing. The definition goes beyond a single score or taste descriptor. Traditionally a 100-point form was used and coffee scoring over 80 counted as specialty; the SCA has since replaced it with the Coffee Value Assessment (CVA).', 'لا تعتمد على كلمة «مختصة» وحدها في الكيس. ابحث عن تاريخ التحميص والمنشأ والمعالجة واسم المنتج، ثم احكم بالتذوق.', 'Do not rely on the word “specialty” on a bag alone. Look for roast date, origin, process and producer, then judge by tasting.', 'SCA — What is specialty coffee?', 'https://sca.coffee/what-is-specialty-coffee', '[{"title":"Royal Coffee — Scoring specialty coffee","url":"https://royalcoffee.com/scoring-specialty-coffee-what-do-the-numbers-mean/"}]'::jsonb, 72, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('blends', 'beans', 'المحصول الواحد والخلطات', 'Single origin and blends', 'المحصول الواحد قهوة من مكان واحد، وقد يعني ذلك قطعة أرض أو مزرعة أو تعاونية أو منطقة. الخلطة اثنتان أو أكثر من هذه القهوات تُباع معًا، وتُخلط قبل التحميص أو بعده. المحامص تخلط للثبات، أي نكهة متقاربة طوال السنة مع تغيّر المواسم، وللتوازن والإبداع؛ مثلًا برازيلي عالي القوام قليل الحموضة مع كولومبي أعلى حموضة. المحصول الواحد يُظهر نكهات مميزة ويسهّل استكشاف أثر المنشأ والمعالجة. ليس أحدهما أفضل دائمًا.', 'A single origin is coffee from one place, which can mean one plot, farm, co-op or region. A blend is two or more such coffees sold together, combined before or after roasting. Roasters blend for consistency, meaning a similar flavor year-round as harvests change, and for balance and creativity; for example a full-bodied, low-acidity Brazilian with a higher-acidity Colombian. Single origins tend to show distinctive flavors and make origin and processing easier to explore. Neither is always better.', 'اقرأ مكونات الخلطة إن ذُكرت. جرّب الخلطة ثم أحد مكوناتها منفردًا بنفس الوصفة لتفهم ماذا أضاف كل بن.', 'Read the blend’s components when listed. Brew the blend and then one component alone with the same recipe to learn what each coffee adds.', 'Trade Coffee — Single origin vs blend', 'https://www.drinktrade.com/blogs/education/difference-between-single-origin-blend-coffee', '[]'::jsonb, 78, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('freshness', 'beans', 'تاريخ التحميص وصمام الكيس', 'Roast dates and the bag valve', 'التحميص يولّد ثاني أكسيد الكربون، والبن يحتاج أن يرتاح ويتخلص من الغاز حتى يسهل تحضيره. كلايف كوفي تذكر أن ذلك يحدث لمعظم البن خلال 4 إلى 14 يومًا بعد التحميص، وأن التحميص الأغمق يجهز أبكر. للإسبريسو توصي محمصة غريتر غودز بانتظار 5 أيام على الأقل. الصمام في الكيس باتجاه واحد: يُخرج الغاز دون إدخال الهواء. اختر كيسًا مكتوبًا عليه تاريخ التحميص. هذه توصيات محامص محددة وليست قاعدة لكل بن.', 'Roasting creates carbon dioxide, and coffee has to rest and degas before it becomes easy to brew. Clive Coffee says that for most coffees this happens 4 to 14 days after roasting, and darker roasts are ready sooner. For espresso, roaster Greater Goods recommends waiting at least 5 days. The valve on the bag is one-way: it lets gas out without letting air in. Choose a bag with a printed roast date. These are specific roasters’ recommendations, not a rule for every coffee.', 'إذا كان الشوت يرش ويفور والكريما كثيرة جدًا والبن محمص قبل أيام قليلة، انتظر يومين وأعد التجربة قبل تغيير الطحن.', 'If a shot sprays and gushes with excessive crema and the coffee was roasted only days ago, wait two days and try again before changing grind.', 'Clive Coffee — Is your coffee too fresh?', 'https://clivecoffee.com/blogs/learn/is-your-coffee-too-fresh', '[]'::jsonb, 72, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roaster-types', 'roasting', 'محمصة الأسطوانة ومحمصة الهواء', 'Drum roasters and air roasters', 'محمصة الأسطوانة تقلّب البن ميكانيكيًّا بدوران الأسطوانة، ومحمصة الهواء (السرير المميّع) ترفع البن بهواء ساخن. المحامص الأسطوانية القديمة اعتمدت على التوصيل فكان التحميص بطيئًا، أما الحديثة فتنقل أغلب الحرارة بالحمل. الهواء الساخن يلامس سطح الحبة كله، لذلك تتقدم تحميصات الهواء أسرع. ميل سيتي تذكر أن الأسطوانة أكثر ثباتًا وتقبل أحجام دفعات مختلفة، بينما محامص الهواء تُبنى غالبًا لحجم دفعة واحد. سويت مارياز وجدت تحميص الهواء أكثر حيوية ولمعانًا مع خطر نقص التطوير، والأسطوانة أعمق نكهة وأثقل قوامًا قليلًا.', 'A drum roaster moves the coffee mechanically with the drum’s rotation; an air (fluid-bed) roaster lofts it with heated air. Early drum roasters relied on conduction, which made roasting slow, while modern ones transfer most heat by convection. Hot air touches the whole bean surface, so air roasts progress faster. Mill City notes drum roasters are more stable and handle a range of batch sizes, while fluid beds are typically built for one batch size. Sweet Maria’s found air roasts livelier and brighter with a risk of underdevelopment, and drum roasts deeper in flavor with slightly more body.', 'لا تنقل وقت تحميص من نوع محمصة إلى آخر. سجّل على محمصتك وقت الاصفرار والفرقعة الأولى والإنزال، وقارن بالطعم لا بالدقائق.', 'Do not carry a roast time from one roaster type to another. On your own machine record yellowing, first crack and drop times, and compare by taste, not minutes.', 'Mill City Roasters — Drum roasters vs fluid bed', 'https://millcityroasters.com/blogs/blog/drum-roasters-vs-fluid-bed', '[{"title":"Sweet Maria’s — Drum roasting vs air roasting","url":"https://library.sweetmarias.com/aug-sept-2003-drum-roasting-vs-air-roasting/"},{"title":"Barista Hustle — Conduction and convection in roasting","url":"https://www.baristahustle.com/lesson/rs-4-02-conduction-and-convection-in-roasting/"}]'::jsonb, 98, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-weight-loss', 'roasting', 'فاقد الوزن في التحميص', 'Roast weight loss', 'البن يفقد وزنًا في التحميص أساسًا لأنه يفقد رطوبته، بينما يكبر حجمه. المعادلة من سويت مارياز: (وزن الأخضر − وزن المحمص) ÷ وزن الأخضر × 100. مثال: 100 غرام تدخل و85 تخرج = 15%. متوسطاتهم التقريبية: نحو 10.3% عند الفرقعة الأولى، 12.7% لدرجة City، 14.5% لـFull City، و15.6% للفرنش. البن الأخضر يصل عادةً برطوبة 10–11%. نوع المحمصة يغيّر الأرقام، فلا تقارن إلا على جهازك.', 'Coffee loses weight in roasting mainly because it loses moisture, while the beans expand in volume. Sweet Maria’s formula: (green weight − roasted weight) ÷ green weight × 100. Example: 100 g in and 85 g out is 15%. Their approximate averages: about 10.3% at first crack, 12.7% for City, 14.5% for Full City and 15.6% for French. Green coffee usually arrives at 10–11% moisture. Roaster type shifts the numbers, so compare only on your own machine.', 'زِن كل دفعة قبل التحميص وبعد التبريد، واكتب النسبة في سجل التحميص. إذا كررت نفس البن ونفس النسبة فأنت قريب من نفس الدرجة.', 'Weigh every batch before roasting and after cooling and write the percentage in your roast log. Repeating the same coffee at the same percentage means you are close to the same roast level.', 'Sweet Maria’s — Calculating roast weight loss', 'https://library.sweetmarias.com/how-to-calculate-weight-loss-in-coffee-roasting/', '[]'::jsonb, 98, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('second-crack', 'roasting', 'الفرقعة الثانية والتحميص الغامق', 'Second crack and dark roasts', 'الفرقعة الأولى سببها الرئيسي تحوّل الماء إلى بخار وصوتها يشبه الفشار. الفرقعة الثانية تحدث عندما يتجاوز تراكم ثاني أكسيد الكربون قدرة بنية الحبة التي صارت هشة، وصوتها طقطقة أخف وأسرع. سويت مارياز تذكر أنها تبدأ قرابة 225–232°م، بعد توقف يتراوح بين 30 ثانية و4 دقائق من نهاية الأولى. تكسّر بنية الحبة يسهّل انتقال الزيوت والغازات إلى السطح، وتصبح رائحة التحميص أكثر حدّة. درجة Full City عند عتبة الفرقعة الثانية، ومنتصفها هو الفرنش.', 'First crack is driven mainly by water turning to steam and sounds like popcorn. Second crack happens when the buildup of carbon dioxide becomes too great for the increasingly brittle bean structure, and it sounds like a lighter, faster snap. Sweet Maria’s places it around 225–232°C (438–450°F), after a pause of roughly 30 seconds to 4 minutes from the end of first crack. The fractured structure lets oils and gases migrate to the surface, and the roast aroma turns more pungent. Full City sits at the threshold of second crack; the middle of it is French roast.', 'قراءة الحرارة تختلف بين المحامص والمجسات، فاعتمد على الصوت والرائحة مع الرقم. الدخان يزداد كثيرًا هنا؛ لا تبتعد عن المحمصة.', 'Temperature readings differ between roasters and probes, so use sound and smell alongside the number. Smoke increases sharply here; stay at the roaster.', 'Sweet Maria’s — First crack and second crack FAQ', 'https://library.sweetmarias.com/first-crack-faq-what-is-first-crack-what-is-second-crack/', '[]'::jsonb, 104, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-for-brew', 'roasting', 'تحميص الإسبريسو وتحميص الفلتر', 'Espresso roasts and filter roasts', 'تحميص الإسبريسو ليس بنًّا أقوى ولا نوعًا مختلفًا من البن الأخضر، بل تحميص يناسب طريقة التحضير. شوت الإسبريسو استخلاص صغير مركّز في ثوانٍ قليلة، لذلك تحمّص إيكاوا له مدة أطول ولونًا أغمق مع تطوير أطول بعد الفرقعة الأولى؛ هذا يزيد الذوبانية ويقلل الحموضة. الفلتر وقت تلامسه أطول، فتكون حرارته القصوى أقل قليلًا وتطويره أقصر، وتظهر النكهات اللامعة. «الأومني» تحميص متوازن يصلح للطريقتين. تحميص الفلتر كإسبريسو يعطي حموضة أوضح ويحتاج طحنًا أنعم.', 'An espresso roast is not stronger coffee or a different green coffee; it is roasted to suit the brewing method. An espresso shot is a small, concentrated extraction lasting only seconds, so IKAWA roasts for it longer and darker with more development after first crack, which increases solubility and reduces acidity. Filter brewing has more contact time, so its maximum temperature is slightly lower and development shorter, letting brighter flavors through. An “omni” roast is balanced to work for both. A filter roast pulled as espresso shows punchier acidity and needs a finer grind.', 'حمّص نفس البن بتطويرين مختلفين، ثم حضّر كل واحد بالطريقتين وسجّل أيهما أنسب. اكتب الهدف، إسبريسو أو فلتر، في سجل كل دفعة.', 'Roast the same coffee with two different development times, brew each both ways and note which suits what. Write the goal, espresso or filter, in each batch’s log.', 'IKAWA — Filter and espresso roasts', 'https://www.ikawacoffee.com/blog/introducing-filter-and-espresso-roasts/', '[{"title":"IKAWA — Roasting for espresso","url":"https://www.ikawacoffee.com/blog/roasting-for-espresso/"},{"title":"Perfect Daily Grind — Omni roasting","url":"https://perfectdailygrind.com/2021/08/top-tips-for-omni-roasting-coffee/"}]'::jsonb, 98, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('roast-safety', 'roasting', 'سلامة التحميص المنزلي', 'Home roasting safety', 'التحميص تجفيف مادة نباتية وإيصالها إلى حافة الاشتعال، فلا تترك المحمصة أبدًا وهي تعمل؛ سويت مارياز تقول ابقَ على مسافة ذراع منها. الدخان يزداد مع الدفعة الأكبر والتحميص الأغمق. الشفاط ينفع إذا كان يطرد الهواء إلى الخارج فعلًا، والأماكن المقترحة شرفة مغطاة أو كراج. فرّغ سلة القشور بين كل تحميصة وأخرى، ولا تزد كمية البن عن حد الجهاز، ولا تستخدم سلك تمديد. بهمور تنبّه: البن قد يشتعل، وعند دخان كثيف أو مزرق اضغط التبريد فورًا.', 'Roasting dries a woody plant material and brings it to the brink of fire, so never walk away from a roaster in use; Sweet Maria’s says to stay within arm’s length. Smoke increases with larger batches and darker roasts. A range hood helps only if it actually vents outside; suggested spots are a covered balcony or garage. Empty the chaff basket between every roast, do not exceed the machine’s batch size, and do not use an extension cord. Behmor warns that coffee beans can ignite, and with heavy or bluish smoke you should press cool immediately.', 'اقرأ دليل محمصتك لإجراء الطوارئ قبل أول تحميصة، وجهّز مكان التبريد مسبقًا. نظّف الزيوت المتراكمة دوريًّا لأنها قد تصير خطر حريق.', 'Read your roaster’s manual for its emergency procedure before the first roast and set up the cooling spot in advance. Clean built-up oils regularly because they can become a fire hazard.', 'Sweet Maria’s — Popper FAQ, tips and troubleshooting', 'https://library.sweetmarias.com/popper-is-a-coffee-roaster-an-introduction/', '[{"title":"Behmor — Roaster quick start guide","url":"https://behmor.com/knowledge-base/behmor-roaster-quick-start-guide/"}]'::jsonb, 99, 'published', false, now())
on conflict (id) do nothing;
insert into public.coffee_lessons (id, course_group, title_ar, title_en, body_ar, body_en, more_ar, more_en, source_title, source_url, supporting_sources, priority, status, requires_review, last_verified_at)
values ('turning-point', 'roasting', 'نقطة التحول ومرحلة التجفيف', 'Turning point and the drying phase', 'حرارة الشحن هي الحرارة التي تبدأ عندها التحميصة، وتختلف بحسب المحمصة وحجم الدفعة والبن. قبل الشحن يقرأ المجس محمصة فارغة ساخنة، وعند إضافة البن بحرارة الغرفة يبرد المجس فتهبط القراءة دقيقة إلى دقيقتين، ثم تتوقف وتبدأ بالصعود: هذه نقطة التحول. إيكاوا توضّح أن البن يسخن فعلًا خلال هذا الهبوط، فبداية المنحنى لا تمثل ما يحدث للحبة، والمجسات تختلف في تأخرها. مرحلة التجفيف تمتد من الشحن حتى تغيّر اللون من الأخضر إلى الأصفر، وغرضها طرد أغلب الماء وبناء الزخم.', 'Charge temperature is the temperature at which the roast begins, and it varies by roaster, batch size and coffee. Before charging, the probe reads an empty, hot roaster; when room-temperature beans are added they cool the probe, so the reading drops for one to two minutes, then stops and starts rising: that is the turning point. IKAWA explains the beans are actually warming during this drop, so the start of the graph does not represent what is happening to them, and probes differ in lag. The drying phase runs from charge to the green-to-yellow color change; its purpose is to expel most of the water and build momentum.', 'قارن نقطة التحول بين دفعاتك على نفس الجهاز فقط: إذا تغيّرت مع ثبات الكمية والشحن فحرارة المحمصة قبل الشحن لم تكن نفسها.', 'Compare turning points only between your own batches on the same machine: if it shifts while batch size and charge stay fixed, the roaster’s heat before charging was not the same.', 'Mill City Roasters — How to read a roast curve', 'https://millcityroasters.com/blogs/blog/how-to-read-a-roast-curve', '[{"title":"IKAWA — Why do IKAWA roasts look different?","url":"https://www.ikawacoffee.com/blog/why-do-ikawa-roasts-look-different/"}]'::jsonb, 98, 'published', false, now())
